// 兼容别名
const OPERATORS_DB = OPERATORS_SWEET_DB;

/**
 * 获取合并了用户自定义修改与多风味选择后的算子候选列表
 * @param {Record<string, string>} customMap 自定义意图覆盖字典 { [opId]: newIntent }
 * @param {string[]} activeFlavors 激活的风味包，如 ['sweet', 'spicy']
 * @param {Array<object>} customDeck 专属自定义生成的算子包 (如小机器人生成的算子)
 */
function getEffectiveOperators(customMap = {}, activeFlavors = ['sweet', 'spicy'], customDeck = []) {
  const flavors = Array.isArray(activeFlavors) && activeFlavors.length > 0 ? activeFlavors : ['sweet', 'spicy'];
  const pool = [];

  if (flavors.includes('sweet')) {
    pool.push(...OPERATORS_SWEET_DB);
  }
  if (flavors.includes('spicy')) {
    pool.push(...OPERATORS_SPICY_DB);
  }
  if (flavors.includes('custom') && Array.isArray(customDeck)) {
    pool.push(...customDeck.map(op => ({ ...op, flavor: 'custom' })));
  }

  // 若用户啥都没选，兜底返回 sweet 库
  const effectiveBase = pool.length > 0 ? pool : OPERATORS_SWEET_DB;

  return effectiveBase.map(op => {
    if (customMap && customMap[op.id]) {
      return {
        ...op,
        intent: customMap[op.id],
        is_customized: true
      };
    }
    return { ...op, is_customized: false };
  });
}

  // =========================================
  // Module: flavor_generator.js
  // =========================================

/**
 * TSE (Tension & Sweetness Engine) - 小机器人自定义 12 算子生成器
 * 模块：flavor_generator.js
 * 核心：基于行协议（Delimited Blocks）的防呆解析与双硬性操作定义契约
 */

/**
 * 构建发送给大模型的生成提示词 (含两大操作定义与 24 黄金示例 Few-Shot)
 */
function buildGeneratorSystemPrompt(userStyleWish) {
  // 组装 24 个黄金示例
  const sweetExamples = OPERATORS_SWEET_DB.map(op => `[${op.id}|${op.name}|${op.quadrant}|anchor:[${op.anchor.join(',')}]]\n意图: ${op.intent}`).join('\n\n');
  const spicyExamples = OPERATORS_SPICY_DB.map(op => `[${op.id}|${op.name}|${op.quadrant}|anchor:[${op.anchor.join(',')}]]\n意图: ${op.intent}`).join('\n\n');

  return `[任务定位]
你是一位顶级互动叙事与戏剧动力学架构师。你的任务是根据用户给出的【世界观风格或风味愿景】，为互动系统生成一套专属于该风格的 12 个情境动力学算子卡组（代号 X1 ~ X12）。

[用户期望的风味与题材]:
${(userStyleWish || '通用全题材剧情冲突与推拉张力').trim()}

[两大核心硬性操作定义（必须绝对无条件遵守）]：
1. 【铁律一：绝对禁止预设玩家言行（Zero Player Presumption）】
   - 严禁预设玩家情绪（禁止出现“玩家感到心动/震惊/愤怒/警惕”等）；
   - 严禁预设玩家言行或动作（禁止出现“玩家巧妙应对/挺身而出/顺水推舟/拔刀相向”等）；
   - 严禁替玩家决定成败（禁止出现“在玩家的威慑下化解了局势”等）；
   - 唯一准则：算子只负责把【客观情势压迫、第三方动机、外部现实难题】摆在台面上，把“如何应对”100% 留白给现场玩家自由抉择。

2. 【铁律二：黑盒泛用原型与情境自涌现（Universal Archetype & Context Emergence）】
   - 【无世界书黑盒警示】：注意！你目前运行在纯净沙盒中，你和系统【均无具体角色卡的世界书与当前背景】！因此，你生成的 12 个算子绝对不是特定剧本，而是【高维、通用于该题材且可即插即用挂载的结构原型（Situational Archetypes）】；
   - 严禁虚构锁定专有名词：严禁凭空生造固定的虚构人名、门派势力名、固定地名或狭隘琐事（如写死特定人名或教室门牌）；
   - 结构化占位与自适应：使用高维泛用代称（如“具备管辖权威的长辈/监督机构”、“正规且受瞩目的考核竞技程序”、“关乎道义声誉的牵连事件”、“客观环境资源的暂时受限”）；
   - 统一自适应起手式：所有算子的 INTENT 统一以“根据当前世界设定与近期上下文，顺理成章/合情合理地引入……”为起手式。运行时由拥有世界书的宿主跑团模型，自动将该原型实例化为该世界下的原生事件！

[X/Y 坐标轴与四象限【客观外部、宏观、叙事导向事件噪音库】契约（严禁更改配额，严格各占 3 个）]：
- X 轴 (言行与行为主动性/进攻姿态): [-1.0 克制内敛/被动防御/隐忍潜伏] ➔ [+1.0 进取主动/直球进攻/主动破局]
- Y 轴 (道德底线/体面顾忌): [-1.0 混沌私欲/打破禁忌/唯利唯欲] ➔ [+1.0 守序自律/在乎名节/顾全大局]

【核心架构定位与设计哲学】：
这 12 个算子不是跟玩家作对的刁难陷阱，而是后台引擎在洞察玩家心理画像后，专门给玩家内心深处的渴望【递刀子、搭戏台、送借口】的外部宏观推手！
后台引擎会实时捕捉玩家当前的【人格心流画像（X/Y 轴）】；一旦识别到玩家流露出某种深层心理欲望，引擎会向现场精准投喂对应频段的【客观外部宏观叙事噪音】，挠到玩家心理深处的痒处，让玩家借题发挥、大呼过瘾！

【噪音生成铁律：世界固有秩序的客观势能】：
所谓的外部叙事噪音，绝非脱离常理的机械降神，更不是无逻辑的天降横祸或凭空蹦出外星人！
它必须是【任何社会生态中普遍存在的必然规律与客观秩序】（如：既定程序的推进、人际网络中的道义牵连、规章制度的例行整饬、自然环境的客观法则、以及迫在眉睫的日程时限）。
噪音只负责由场外向场内“注水搭台”，绝对严禁描写任何玩家的言行或心理反应！“外部舞台怎么搭、噪音怎么响，由算子决定；戏怎么演、怎么借题发挥，100% 交由现场玩家自主决定！”

