/**
 * 鲁棒性行协议定界块解析器 (Delimited Blocks Parser)
 * 具备极强容错能力：免疫 Markdown 围栏、容忍尾部截断，不足 12 个时自动用备用库优雅补齐
 */
function parseDelimitedOperators(rawText) {
  if (!rawText || typeof rawText !== 'string') return [];

  const operators = [];
  const blockRegex = /===OPERATOR_START===([\s\S]*?)===OPERATOR_END===/gi;
  let match;

  while ((match = blockRegex.exec(rawText)) !== null) {
    const blockContent = match[1];
    const op = parseSingleBlock(blockContent);
    if (op && op.name && op.intent) {
      operators.push(op);
    }
  }

  // 容错处理：如果大模型在最后一个算子处被 token 截断，尝试提取未闭合的末尾块
  if (operators.length < 12) {
    const trailingMatch = rawText.match(/===OPERATOR_START===([\s\S]*)$/i);
    if (trailingMatch) {
      const trailingContent = trailingMatch[1];
      if (!trailingContent.includes('===OPERATOR_END===')) {
        const op = parseSingleBlock(trailingContent);
        if (op && op.name && op.intent) {
          // 避免重复推入
          if (!operators.find(o => o.id === op.id)) {
            operators.push(op);
          }
        }
      }
    }
  }

  // 象限补齐与规范化（确保 12 个算子，ID 为 X1~X12，四象限健全）
  const finalDeck = [];
  const defaultSlotMapping = [
    { id: 'X1', quadrant: 'Q1', anchor: [0.75, 0.45], fallback: OPERATORS_SPICY_DB[0] },
    { id: 'X2', quadrant: 'Q1', anchor: [0.65, 0.75], fallback: OPERATORS_SPICY_DB[1] },
    { id: 'X3', quadrant: 'Q1', anchor: [0.45, 0.60], fallback: OPERATORS_SPICY_DB[2] },
    { id: 'X4', quadrant: 'Q2', anchor: [-0.65, 0.75], fallback: OPERATORS_SPICY_DB[3] },
    { id: 'X5', quadrant: 'Q2', anchor: [-0.50, 0.55], fallback: OPERATORS_SPICY_DB[4] },
    { id: 'X6', quadrant: 'Q2', anchor: [-0.75, 0.40], fallback: OPERATORS_SPICY_DB[5] },
    { id: 'X7', quadrant: 'Q3', anchor: [-0.70, -0.65], fallback: OPERATORS_SPICY_DB[6] },
    { id: 'X8', quadrant: 'Q3', anchor: [-0.55, -0.50], fallback: OPERATORS_SPICY_DB[7] },
    { id: 'X9', quadrant: 'Q3', anchor: [-0.80, -0.35], fallback: OPERATORS_SPICY_DB[8] },
    { id: 'X10', quadrant: 'Q4', anchor: [0.75, -0.60], fallback: OPERATORS_SPICY_DB[9] },
    { id: 'X11', quadrant: 'Q4', anchor: [0.55, -0.75], fallback: OPERATORS_SPICY_DB[10] },
    { id: 'X12', quadrant: 'Q4', anchor: [0.80, -0.30], fallback: OPERATORS_SPICY_DB[11] }
  ];

  for (let i = 0; i < 12; i++) {
    const slot = defaultSlotMapping[i];
    const candidate = operators[i];

    if (candidate && candidate.intent) {
      finalDeck.push({
        id: slot.id,
        name: candidate.name || `自定义算子·${slot.id}`,
        flavor: 'custom',
        quadrant: candidate.quadrant || slot.quadrant,
        anchor: candidate.anchor && candidate.anchor.length === 2 ? candidate.anchor : slot.anchor,
        intent: candidate.intent,
        freedom_directive: candidate.freedom_directive || '顺应情境自然推演，严禁替玩家预设动作。'
      });
    } else {
      // 容错回退补齐
      const fb = slot.fallback;
      finalDeck.push({
        id: slot.id,
        name: `${fb.name} (定制补全版)`,
        flavor: 'custom',
        quadrant: slot.quadrant,
        anchor: slot.anchor,
        intent: fb.intent,
        freedom_directive: fb.freedom_directive || '顺应情境自然推演，严禁替玩家预设动作。'
      });
    }
  }

  return finalDeck;
}

/**
 * 解析单个定界块内容
 */
function parseSingleBlock(text) {
  if (!text) return null;
  const result = {};

  const idMatch = text.match(/ID\s*:\s*([^\r\n]+)/i);
  if (idMatch) result.id = idMatch[1].trim();

  const nameMatch = text.match(/NAME\s*:\s*([^\r\n]+)/i);
  if (nameMatch) result.name = nameMatch[1].trim();

  const quadMatch = text.match(/QUADRANT\s*:\s*([^\r\n]+)/i);
  if (quadMatch) result.quadrant = quadMatch[1].trim().toUpperCase();

  const anchorMatch = text.match(/ANCHOR\s*:\s*\[?(-?[\d.]+)\s*,\s*(-?[\d.]+)\]?/i);
  if (anchorMatch) {
    result.anchor = [parseFloat(anchorMatch[1]), parseFloat(anchorMatch[2])];
  }

  const intentMatch = text.match(/INTENT\s*:\s*([\s\S]*?)(?=DIRECTIVE|===|$)/i);
  if (intentMatch) result.intent = intentMatch[1].trim();

  const dirMatch = text.match(/DIRECTIVE\s*:\s*([\s\S]*?)(?====|$)/i);
  if (dirMatch) result.freedom_directive = dirMatch[1].trim();

  return result;
}

/**
 * 调用酒馆助手纯净沙盒 API 异步生成自定义卡组
 * 绝对隔离原则：
 * 1. 优先使用 generateRaw + ordered_prompts，不引用任何酒馆预设、世界书、角色卡与上下文历史；
 * 2. 降级使用 generate 时通过 overrides 强行清空一切宿主污染；
 * 3. 不做任何预设破限兜底，保持纯粹的结构化元数据工具语义。
 * 
 * @param {string} userStyleWish 用户输入的主题愿景
 * @param {Function} getApi 获取 API 的辅助函数
 * @param {Function} onProgress 进度回调 (statusText)
 * @returns {Promise<Array<object>>} 返回合规的 12 个自定义算子
 */
async function generateCustomDeckAsync(userStyleWish, getApi, onProgress = () => {}, timeoutSec = 240) {
  const generateRaw = getApi('generateRaw');
  const generate = getApi('generate');

  if (typeof generateRaw !== 'function' && typeof generate !== 'function') {
    throw new Error('未检测到酒馆助手 generateRaw / generate 接口，无法调用主 API 自动生成。');
  }

  const userContent = buildGeneratorSystemPrompt(userStyleWish);
  const systemRole = '你是一位严谨的互动叙事与戏剧动力学架构师。严格遵循行协议定界块格式输出 12 个算子，绝不寒暄，绝不输出 Markdown 围栏，直接输出算子内容。';

  const timeoutMs = (typeof timeoutSec === 'number' && timeoutSec > 0) ? timeoutSec * 1000 : 240000;
  onProgress(`✨ 正在以纯净沙盒通道连接主 API (防卡死超时保护: ${Math.round(timeoutMs / 1000)}s)...`);

  try {
    const executeApiCall = async () => {
      if (typeof generateRaw === 'function') {
        // 方案 A（首选）：调用 generateRaw，纯净白板沙盒通道
        // ordered_prompts 仅包含 system 和 user，底层自动跳过 preset、world_info、char_description、chat_history
        return await generateRaw({
          user_input: '',
          ordered_prompts: [
            { role: 'system', content: systemRole },
            { role: 'user', content: userContent }
          ],
          max_chat_history: 0,
          should_silence: true,
          custom_api: {
            temperature: 0.7,
            max_tokens: 30000
          }
        });
      } else {
        // 方案 B（向下兼容降级）：使用 generate 并通过 overrides 强行清空所有外部污染源
        return await generate({
          user_input: userContent,
          max_chat_history: 0,
          should_silence: true,
          overrides: {
            char_description: '',
            char_personality: '',
            scenario: '',
            world_info_before: '',
            world_info_after: '',
            dialogue_examples: '',
            chat_history: { prompts: [] }
          },
          injects: [
            { role: 'system', content: systemRole, position: 'in_chat', depth: 0 }
          ],
          custom_api: {
            temperature: 0.7,
            max_tokens: 30000
          }
        });
      }
    };

    let timerId = null;
    const timeoutPromise = new Promise((_, reject) => {
      timerId = setTimeout(() => {
        reject(new Error(`生成请求超时（已等待超过 ${Math.round(timeoutMs / 1000)} 秒）。模型后端无响应或网络中断，已自动中止以防界面假死。请检查网络通道后重试。`));
      }, timeoutMs);
      if (timerId && typeof timerId.unref === 'function') timerId.unref();
    });

    let response;
    try {
      response = await Promise.race([executeApiCall(), timeoutPromise]);
    } finally {
      if (timerId) clearTimeout(timerId);
    }

    onProgress('📝 正在执行行协议防呆解析与四象限拓扑校验...');
    const rawOutput = (typeof response === 'string') ? response : (response && (response.text || response.result || ''));

    const deck = parseDelimitedOperators(rawOutput);
    if (!deck || deck.length !== 12) {
      throw new Error(`解析生成的算子数量异常 (期望 12，实际 ${deck ? deck.length : 0})`);
    }

    onProgress('🎉 专属 12 算子甲板构建完成！');
    return deck;
  } catch (err) {
    console.error('[TSE Flavor Generator] 自动生成失败:', err);
    throw err;
  }
}

