/**
 * TSE (Tension & Sweetness Engine) - 卡组状态机与人类可读楼层状态追踪
 * 模块：state_machine.js
 */

const SMOOTH_ALPHA = 0.25;      // 贝叶斯平滑因子
const DEADBAND = 0.15;          // 滞后死区阈值（防边界震荡）
const DEFAULT_TTL = 2;          // 发糖卡牌默认生命周期 (回合数)
const DEFAULT_COOLDOWN = 1;     // 发糖卡牌默认冷却CD (间歇回合数)
const COOLDOWN_MAX = 3;         // 局部 CD 队列深度

/**
 * 构建 3主6临 动态卡组 (支持大牌库不放回消耗轮替、多风味均衡配额、疲态自适应加权与象限弹性解冻)
 * @param {[number, number]} coord 当前坐标
 * @param {string} quadrant 当前确认象限
 * @param {Record<string, string>} customOperators 用户自定义套路词典
 * @param {string[]} activeFlavors 激活的风味列表，如 ['sweet', 'spicy']
 * @param {Array<object>} customDeck 专属自定义生成的算子包
 * @param {boolean} pacingFatigue 是否处于低投入疲态 (若为 true，劲辣算子优先推荐)
 * @param {string[]} graveyard 当前大牌库已消耗进墓地的算子 ID 列表 (用于不放回抽取轮替)
 */
function buildHand(coord, quadrant, customOperators = {}, activeFlavors = ['sweet', 'spicy'], customDeck = [], pacingFatigue = false, graveyard = []) {
  const flavors = Array.isArray(activeFlavors) && activeFlavors.length > 0 ? activeFlavors : ['sweet', 'spicy'];
  const ops = getEffectiveOperators(customOperators, flavors, customDeck);
  const deadSet = new Set(Array.isArray(graveyard) ? graveyard : []);

  // 1. 计算所有算子到当前坐标的欧氏距离 (含疲态加权)
  const listWithDist = ops.map(op => {
    const anchor = (Array.isArray(op.anchor) && op.anchor.length >= 2) ? op.anchor : [0, 0];
    const safeCoord = (Array.isArray(coord) && coord.length >= 2) ? coord : [0, 0];
    const dx = anchor[0] - safeCoord[0];
    const dy = anchor[1] - safeCoord[1];
    let dist = Math.hypot(dx, dy);

    // 若检测到心流疲态，给予劲辣（辣条）算子 -0.4 的强力距离吸附加权，优先出牌破局
    if (pacingFatigue && op.flavor === 'spicy') {
      dist = Math.max(0, dist - 0.4);
    }

    return {
      ...op,
      dist: dist,
      is_exhausted: deadSet.has(op.id)
    };
  });

  // 分离当前象限候选与跨象限候选
  const inQuad = listWithDist.filter(op => op.quadrant === quadrant);
  const outQuad = listWithDist.filter(op => op.quadrant !== quadrant);

  // 区分：未出场算子 (优先) 与 墓地算子 (用于弹性解冻)
  const availableInQuad = inQuad.filter(op => !op.is_exhausted);
  const exhaustedInQuad = inQuad.filter(op => op.is_exhausted);

  // 2. 主卡：同象限内 3 张 (耐受度 = 2) - 多风味均衡配额抽样
  const selectedPrimary = [];
  const primaryCapacity = 3;
  const basePrimaryPerFlavor = Math.floor(primaryCapacity / flavors.length);

  // 第一阶段：优先从未出场池中按多风味均衡配额抽取
  for (const f of flavors) {
    if (selectedPrimary.length >= primaryCapacity) break;
    const fInQuad = availableInQuad
      .filter(op => (op.flavor || 'sweet') === f && !selectedPrimary.some(p => p.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const take = fInQuad.slice(0, basePrimaryPerFlavor);
    selectedPrimary.push(...take);
  }

  // 第二阶段：若未出场池中仍有名额未满，从所有未入选同象限未出场算子中按距离最近补齐
  if (selectedPrimary.length < primaryCapacity) {
    const remainingAvailableInQuad = availableInQuad
      .filter(op => !selectedPrimary.some(p => p.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const needed = primaryCapacity - selectedPrimary.length;
    selectedPrimary.push(...remainingAvailableInQuad.slice(0, needed));
  }

  // 第三阶段【弹性解冻 (Soft Recall)】：若该象限未出场算子不足，从同象限墓地借调距离最近的算子补齐 3 张！
  if (selectedPrimary.length < primaryCapacity) {
    const remainingExhaustedInQuad = exhaustedInQuad
      .filter(op => !selectedPrimary.some(p => p.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const needed = primaryCapacity - selectedPrimary.length;
    selectedPrimary.push(...remainingExhaustedInQuad.slice(0, needed));
  }

  const primaryPool = selectedPrimary.map(op => ({
    id: op.id,
    name: op.name,
    flavor: op.flavor || 'sweet',
    quadrant: op.quadrant,
    intent: op.intent,
    type: 'primary',
    durability: 2
  }));

  // 3. 临卡：跨象限内 6 张 (耐受度 = 1) - 多风味均衡配额抽样
  const availableOutQuad = outQuad.filter(op => !op.is_exhausted);
  const exhaustedOutQuad = outQuad.filter(op => op.is_exhausted);

  const selectedAdjacent = [];
  const adjacentCapacity = 6;
  const baseAdjacentPerFlavor = Math.floor(adjacentCapacity / flavors.length);

  // 第一阶段：优先从未出场池中跨象限按多风味均衡配额抽取
  for (const f of flavors) {
    if (selectedAdjacent.length >= adjacentCapacity) break;
    const fOutQuad = availableOutQuad
      .filter(op => (op.flavor || 'sweet') === f && !selectedAdjacent.some(a => a.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const take = fOutQuad.slice(0, baseAdjacentPerFlavor);
    selectedAdjacent.push(...take);
  }

  // 第二阶段：从剩余未出场跨象限算子中补齐
  if (selectedAdjacent.length < adjacentCapacity) {
    const remainingAvailableOutQuad = availableOutQuad
      .filter(op => !selectedAdjacent.some(a => a.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const needed = adjacentCapacity - selectedAdjacent.length;
    selectedAdjacent.push(...remainingAvailableOutQuad.slice(0, needed));
  }

  // 第三阶段【弹性解冻 (Soft Recall)】：若跨象限未出场算子不足，从墓地借调补齐 6 张！
  if (selectedAdjacent.length < adjacentCapacity) {
    const remainingExhaustedOutQuad = exhaustedOutQuad
      .filter(op => !selectedAdjacent.some(a => a.id === op.id))
      .sort((a, b) => a.dist - b.dist);
    const needed = adjacentCapacity - selectedAdjacent.length;
    selectedAdjacent.push(...remainingExhaustedOutQuad.slice(0, needed));
  }

  const adjacentPool = selectedAdjacent.map(op => ({
    id: op.id,
    name: op.name,
    flavor: op.flavor || 'sweet',
    quadrant: op.quadrant,
    intent: op.intent,
    type: 'adjacent',
    durability: 1
  }));

  return [...primaryPool, ...adjacentPool];
}

/**
 * 判定象限归属（含 ±DEADBAND 防抖死区）
 */
function detectQuadrant(x, y, currentQuadrant) {
  if (x > DEADBAND && y > DEADBAND) return 'Q1';
  if (x < -DEADBAND && y > DEADBAND) return 'Q2';
  if (x < -DEADBAND && y < -DEADBAND) return 'Q3';
  if (x > DEADBAND && y < -DEADBAND) return 'Q4';
  return currentQuadrant; // 处于死区内，维持现状，杜绝震荡
}

/**
 * 格式化输出【人类完全可读】的发牌预约与楼层追踪状态
 * @param {object} state TSE 引擎状态
 * @param {number} currentFloor 当前最新楼层索引 (0-based)
 */
function formatHumanReadableFloorStatus(state, currentFloor = 0) {
  const currentFloorHuman = currentFloor >= 0 ? currentFloor + 1 : 1;
  const currentFloorDesc = `第 ${currentFloorHuman} 楼 (索引号: ${currentFloor})`;
  const committedFloor = (typeof state.committed_floor === 'number') ? state.committed_floor : -1;
  const committedFloorDesc = committedFloor >= 0 ? `第 ${committedFloor + 1} 楼` : '尚未定稿';
  const hasDraft = !!state.draft_meta;
  const draftNotice = hasDraft
    ? `📝 当前捕获到候选草稿 (目标:[${state.draft_meta.target || '无'}]) · 待接话后定稿锁定，重Roll不耗卡牌`
    : '已完全与定稿历史同步';

  const totalDuration = (state.settings && typeof state.settings.sweet_duration === 'number') ? state.settings.sweet_duration : DEFAULT_TTL;
  const totalCooldown = (state.settings && typeof state.settings.sweet_cooldown === 'number') ? state.settings.sweet_cooldown : DEFAULT_COOLDOWN;

  const fatigueTag = state.pacing_fatigue ? ' ⚡[疲态破局加速中]' : '';

  if (state.active_buff) {
    const buff = state.active_buff;
    const startHuman = (typeof buff.start_floor === 'number') ? buff.start_floor + 1 : currentFloorHuman;
    const endHuman = (typeof buff.end_floor === 'number') ? buff.end_floor + 1 : startHuman + (buff.remaining_ttl || 1);
    const ttl = buff.remaining_ttl ?? 1;

    let flavorBadge = '🎯 发牌生效中';
    if (buff.flavor === 'spicy') flavorBadge = '🌶️ 劲辣破局中';
    else if (buff.flavor === 'custom') flavorBadge = '🎨 定制算子生效中';
    else flavorBadge = '🍬 蜜糖心流中';

    return {
      mode: 'ACTIVE',
      status_badge: flavorBadge + fatigueTag,
      title: `【${buff.name}】`,
      flavor: buff.flavor || 'sweet',
      current_floor_desc: currentFloorDesc,
      committed_floor_desc: committedFloorDesc,
      interval_desc: `第 ${startHuman} 楼 启动 ➔ 持续生效至 第 ${endHuman} 楼`,
      remaining_desc: `剩余有效生命周期: ${ttl} 回合 (保底上限 ${totalDuration} 回合 · 支持达成即出)`,
      target_desc: buff.target && buff.target !== 'none' ? buff.target : '通用推进',
      note_desc: buff.note || '等待模型第一轮生成捕捉...',
      draft_notice: draftNotice,
      human_summary: `正在打出卡牌【${buff.name}】(${buff.flavor === 'spicy' ? '劲辣宏观情势' : '蜜糖心流'})。从第 ${startHuman} 楼生效至第 ${endHuman} 楼（剩余 ${ttl} 回合 · 保底 ${totalDuration} 回合）。目标聚焦: [${buff.target || '全场'}代入]。${hasDraft ? '（检测到最新回复草稿，将在您接话后正式锁定）' : ''}`
    };
  }

  if (state.cool_off_turns > 0) {
    return {
      mode: 'COOLING_OFF',
      status_badge: '☕ 蓄水沉淀期' + fatigueTag,
      title: '剧情自由呼吸与蓄水发酵',
      current_floor_desc: currentFloorDesc,
      committed_floor_desc: committedFloorDesc,
      interval_desc: `当前处于间歇期 (剩余 ${state.cool_off_turns} 回合 · 总CD ${totalCooldown} 回合)`,
      remaining_desc: `将在下一回合后恢复智能发牌`,
      target_desc: state.last_target || '无',
      note_desc: state.last_note || '剧情自然推演中...',
      draft_notice: draftNotice,
      human_summary: `上一张卡牌已平稳到期或达成核销，当前进入蓄水沉淀期（剩余 ${state.cool_off_turns} 回合 · 总CD ${totalCooldown} 回合），给剧情留出自然呼吸空间。${state.pacing_fatigue ? '检测到玩家低字数疲态，已激活破局加速！' : ''}`
    };
  }

  return {
    mode: 'STANDBY',
    status_badge: '✨ 待机就绪' + fatigueTag,
    title: '智能卡池已就绪',
    current_floor_desc: currentFloorDesc,
    committed_floor_desc: committedFloorDesc,
    interval_desc: '待发牌状态',
    remaining_desc: '下一轮 AI 回复时立即触发抽牌',
    target_desc: state.last_target || '无',
    note_desc: state.last_note || '等待下一轮心流交互...',
    draft_notice: draftNotice,
