  };
}

/**
 * 观察值全域双向动力学离心阻尼函数 (Dual-direction Dynamic Centrifugal Damping)
 * 算法哲学背景与社会演化博弈依据：
 * 1. 【打破人类与模型的 Q1 平庸温水沉降】：
 *    - 演化生物学（ESS）与社会学决定了人类在绝大多数日常社交中天然是合作守序的（聚集在 Q1）；
 *    - 大语言模型在 RLHF 对齐后更是具有顽固的讨好型迎合倾向（Sycophancy Bias），充斥着廉价好人打分；
 *    - 若按现实绝对道德测谎，所有玩家都会陷在 Q1 蜗角之地，使 Q2(狂放)、Q3(阴湿)、Q4(克制) 三大高张力戏剧原型彻底沦为死区。
 * 2. 【正向细水长流幂次阻尼 (v >= 0)】：
 *    - v^1.6 幂次压缩：日常寒暄 (+0.3) 折半至 +0.146，低分杂音 (+0.1) 折损 75%，但顶格深情 (+1.0) 完美无损保全。
 * 3. 【负向真·坏事传千里：早期饱和式离心放大 (v < 0)】：
 *    - 小摩擦日常守护 (-0.30 <= v < 0)：1:1 自然穿透，保护情侣日常拌嘴、傲娇嘴硬的情趣，绝不上纲上线；
 *    - 冲突区超高斜率放大与早期顶格 (-0.70 <= v < -0.30)：
 *      * 鉴于 LLM 在实际交互中几乎极少主动给出 -0.9/-1.0（-0.6~-0.7 已等同于决裂），算法直接在 -0.70 处饱和打满 -1.000！
 *      * 公式：0.30 + 0.70 * ((|v| - 0.30) / 0.40)^0.85
 *      * -0.35 -> -0.420 (开始拉伸)
 *      * -0.40 -> -0.515 (冷战拉开，放大 +28.8%)
 *      * -0.50 -> -0.688 (发生违约，放大 +37.6%，直抵负向深水区)
 *      * -0.60 -> -0.848 (严重破戒，放大 +41.3%，逼近决裂边缘)
 *      * -0.70 -> -1.000 (反目成仇，无需等模型给 -1.0，直接触发顶格极刑！)
 *      * v < -0.70 -> -1.000 (饱和安全截断)
 *
 * @param {number} val 原始观察值 [-1.0, 1.0]
 * @returns {number} 动力学修正后的观察值 [-1.0, 1.0]
 */
function dampObsDynamic(val) {
  if (typeof val !== 'number' || isNaN(val)) return 0;
  if (val >= 0) {
    const clamped = Math.min(1, val);
    return Number(Math.pow(clamped, 1.6).toFixed(3));
  }
  const u = Math.min(1, Math.abs(val));
  if (u <= 0.30) {
    return Number((-u).toFixed(3));
  }
  if (u >= 0.70) {
    return -1.0;
  }
  const x = (u - 0.30) / 0.40;
  const boosted = 0.30 + 0.70 * Math.pow(x, 0.85);
  return Number((-boosted).toFixed(3));
}

