/**
/**
 * 决策当前 DMP 推荐目标角色与是否触发 10% 远方羁绊回响
 * 遵循【2-2-2-4 动态轮盘分流法】与确定性楼层伪随机：
 * 1. 2成概率 (20%) -> 候选榜首 (Rank 1)；
 * 2. 2成概率 (20%) -> 候选第二名 (Rank 2)；
 * 3. 2成概率 (20%) -> 候选第三名 (Rank 3)；
 * 4. 4成概率 (40%) -> 现场完全留白 (不指定角色，由大模型自主指派现场最适宜人物)；
 * 5. 特殊机制：仅当历史总榜第一名不在最近 10 回合时，其在前 10% 概率触发远方羁绊回响；
 * 6. 确定性哈希保证同楼层 Swipe/重生成 结果稳定不抖动。
 */
function resolveDmpTarget(dmp, floorId = 0) {
  const safeDmp = dmp || {};
  const affinity = safeDmp.affinity_targets || {};
  const recent = Array.isArray(safeDmp.recent_targets) ? safeDmp.recent_targets : [];

  // 历史总榜降序 (过滤零值，频次相同时按名称稳定排序防抖动)
  const allTimeSorted = Object.entries(affinity)
    .filter(([_, cnt]) => typeof cnt === 'number' && cnt > 0)
    .sort((a, b) => (b[1] - a[1]) || a[0].localeCompare(b[0]));
  const topAllTime = allTimeSorted.length > 0 ? allTimeSorted[0][0] : null;

  // 最近 10 回合频次降序 (频次相同时，优先按最后一次交互出现的位置打破平票，最新互动者胜出)
  const recentFreq = {};
  for (const name of recent) {
    if (name) recentFreq[name] = (recentFreq[name] || 0) + 1;
  }
  const recentSorted = Object.entries(recentFreq).sort((a, b) => {
    const diff = b[1] - a[1];
    if (diff !== 0) return diff;
    return recent.lastIndexOf(b[0]) - recent.lastIndexOf(a[0]);
  });
  const topRecent = recentSorted.length > 0 ? recentSorted[0][0] : null;

  // 候选去重序列：优先最近 10 回合活跃角色，其次总榜前列补充
  const candidateList = [];
  const addCand = (name) => {
    if (name && !candidateList.includes(name)) candidateList.push(name);
  };
  for (const [name] of recentSorted) addCand(name);
  for (const [name] of allTimeSorted) addCand(name);

  // 确定性伪随机哈希 (0~1)
  const seed = Math.abs(Number(floorId) || 0);
  const pseudoRoll = ((seed * 9301 + 49297) % 233280) / 233280;

  let target = null;
  let isRemoteEcho = false;
  let dispatchMode = 'free'; // 'remote_echo' | 'rank1' | 'rank2' | 'rank3' | 'free'

  // 1. 优先判定 10% 远方羁绊回响：
  // 仅当历史总榜榜首存在且不在最近 10 回合滑动窗口内时，且掷骰落在前 10% (0.00 ~ 0.10)
  if (topAllTime && !recent.includes(topAllTime) && pseudoRoll < 0.10) {
    target = topAllTime;
    isRemoteEcho = true;
    dispatchMode = 'remote_echo';
  } else {
    // 2. 【2-2-2-4 动态轮盘分流法】
    // 顺应楼层基准偏置，将轮盘区间划分为：
    // [0.00, 0.20): 2成概率 -> 榜首 (Rank 1)
    // [0.20, 0.40): 2成概率 -> 次席 (Rank 2)
    // [0.40, 0.60): 2成概率 -> 第三席 (Rank 3)
    // [0.60, 1.00): 4成概率 -> 纯留白，不指定角色，由 LLM 根据现场人物自主调度
    const rankRoll = (pseudoRoll + 0.79) % 1.0;
    if (rankRoll < 0.20) {
      target = candidateList[0] || null;
      dispatchMode = 'rank1';
    } else if (rankRoll < 0.40) {
      target = candidateList[1] || candidateList[0] || null;
      dispatchMode = candidateList[1] ? 'rank2' : (candidateList[0] ? 'rank1' : 'free');
    } else if (rankRoll < 0.60) {
      target = candidateList[2] || candidateList[0] || null;
      dispatchMode = candidateList[2] ? 'rank3' : (candidateList[0] ? 'rank1' : 'free');
    } else {
      target = null;
      dispatchMode = 'free';
    }
  }

  return {
    target,
    isRemoteEcho,
    dispatchMode,
    candidateList,
    topAllTime,
    topRecent,
    allTimeSorted,
    recentSorted
  };
}

