    : '';

  const noteSection = safeBuff.note ? `- 玩家前一轮隐秘心流洞察: 【${safeBuff.note}】（此为玩家前序推拉所投射的核心情绪诉求与期待反馈。请将其作为博弈背景，配合上方核心意图自然流转——无需直白点破，赋予角色心领神会的敏锐与洞察，在互动推拉中让玩家感受到棋逢对手、智力上的意外俏皮感，严禁生搬硬套文字）` : '';

  const floorId = (safeBuff && typeof safeBuff.start_floor === 'number') ? safeBuff.start_floor : 0;
  const { target: resolvedTarget, isRemoteEcho } = resolveDmpTarget(dmp, floorId);

  let targetDesc = resolvedTarget;
  if (!targetDesc && safeBuff.target && safeBuff.target !== 'none') {
    targetDesc = safeBuff.target;
  }

  // 风味感知型 target 语义重塑 (含 10% 远方羁绊主动关切 与 绝对防空降安全防线)
  let targetSection = '';
  if (safeBuff.flavor === 'spicy') {
    if (isRemoteEcho && targetDesc) {
      targetSection = `- 远方羁绊急变与突发波及: [${targetDesc}]（远方故人主动传来急件/托人捎带口信/或其在远方陷入变故自然波及现场；重点呈现突发变数打破单一主角主动，严禁替玩家预设应对方式）`;
    } else if (targetDesc) {
      targetSection = `- 现场受力角色与羁绊支点: [${targetDesc}]（此宏观事件应作为外部冲击自然波及现场与该角色；建议结合现场局势灵活调度，如该角色当前不在场切勿突兀瞬移空降，亦可由现场最适宜的角色承接波澜，重点呈现其面对突发变数的本能反应与神态反差，借势引爆戏剧张力，严禁替玩家预设应对方式）`;
    } else {
      targetSection = `- 现场受力角色与羁绊支点: 当前现场最适宜的角色（此宏观事件应作为外部冲击自然波及现场；顺应当前剧情与场景自然流转，根据在场人物表现灵活承接，重点呈现其面对突发变数的本能反应与神态反差，借势引爆戏剧张力，严禁替玩家预设应对方式，切勿突兀瞬移空降）`;
    }
  } else {
    // 蜜糖或自定义
    if (isRemoteEcho && targetDesc) {
      targetSection = `- 远方羁绊回响 (主动关切): [${targetDesc}]（远方角色主动对玩家产生剧情干涉，如：飞鸽急件、托故人捎带贴身物件、得知主角下落后主动寻来、或白描其在远方的心境挂念；打破只有主角主动的单调格局）`;
    } else if (targetDesc) {
      targetSection = `- 推荐互动角色: [${targetDesc}]（建议结合现场局势灵活调度；如该角色当前不在场切勿突兀瞬移空降，亦可由现场最适宜的角色承接推拉，围绕其展开互动福利与心流奖励，将外部情境化为彼此靠近、情感升温或默契发糖的天然契机）`;
    } else {
      targetSection = `- 推荐互动角色: 当前现场最适宜的角色（顺应当前剧情与场景自然流转，根据在场人物表现灵活承接推拉，切勿突兀瞬移空降，将外部情境化为彼此靠近、情感升温或默契发糖的天然契机）`;
    }
  }

  const flavorPositioning = safeBuff.flavor === 'spicy'
    ? '戏剧刺激 · 破除死水'
    : '情感福利 · 亲密犒赏';

  let content = template
    .replace(/\{\{flavor_positioning\}\}/g, flavorPositioning)
    .replace(/\{\{name\}\}/g, safeBuff.name || '')
    .replace(/\{\{intent\}\}/g, safeBuff.intent || '')
    .replace(/\{\{archetype_section\}\}/g, archetypeSection)
    .replace(/\{\{archetype_name\}\}/g, arch ? arch.name : '')
    .replace(/\{\{archetype_desire\}\}/g, arch ? arch.desire : '')
    .replace(/\{\{archetype_guide\}\}/g, arch ? arch.guide : '')
    .replace(/\{\{note_section\}\}/g, noteSection)
    .replace(/\{\{note\}\}/g, safeBuff.note || '')
    .replace(/\{\{target_section\}\}/g, targetSection)
    .replace(/\{\{target\}\}/g, targetDesc || '')
    .replace(/\{\{focus_section\}\}/g, '')
    .replace(/\{\{focus\}\}/g, '');

  // 首部双换行物理空行隔离，确保与上一层人设/世界书标签（如 </状态栏格式> 或 </角色设定>）有清晰的段落空行
  return '\n\n' + content.replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

/**
 * 注入 D1 常驻伴生协议（免手动配置世界书）
 */
function injectCompanionProtocol(getApi, settings = {}) {
  const inject = getApi('injectPrompts');
  const uninject = getApi('uninjectPrompts');
  if (!inject) return;

  if (uninject) {
    uninject([COMPANION_PROTOCOL_ID]);
  }

  const depth = (typeof settings.d1_depth === 'number') ? settings.d1_depth : 1;
  let rawText = (settings.d1_protocol || DEFAULT_COMPANION_PROTOCOL).trim();

  // 若未包含任何外层 XML 标签，自动补齐 <companion_protocol> 隔离标签
  if (!rawText.startsWith('<') && !rawText.includes('<companion_protocol>')) {
    rawText = `<companion_protocol>\n${rawText}\n</companion_protocol>`;
  }

  // 首部双换行物理空行隔离，彻底杜绝与上方 </状态栏格式> 紧贴黏连
  const content = '\n\n' + rawText + '\n';

  inject([{
    id: COMPANION_PROTOCOL_ID,
    position: 'in_chat',
    depth: depth,
    role: 'system',
    content: content,
    should_scan: false
  }]);
}

/**
 * 注入 D0 发糖导向卡牌（融入 DMP 推荐流、微观心流白描与四象限人格画像破局航标）
 */
function injectD0Prompt(getApi, buff, dmp, settings = {}, state = {}) {
  const inject = getApi('injectPrompts');
  const uninject = getApi('uninjectPrompts');
  if (!inject) return;

  if (uninject) {
    uninject([INJECT_ID]);
  }

  const depth = (typeof settings.d0_depth === 'number') ? settings.d0_depth : 0;
  const content = buildD0PromptContent(buff, dmp, settings, state);

  inject([{
    id: INJECT_ID,
    position: 'in_chat',
    depth: depth,
    role: 'system',
    content: content,
    should_scan: false
  }]);
}

function uninjectAllPrompts(getApi) {
  const uninject = getApi('uninjectPrompts');
  if (uninject) {
    uninject([INJECT_ID, COMPANION_PROTOCOL_ID]);
  }
}

