/**
 * TSE (Tension & Sweetness Engine) - 隐形清洗守卫与宿主正则自举
 * 模块：regex_cleaner.js
 * 铁律：仅挂载全局正则，绝对严禁挂载 { type: 'character' }（彻底根治“未能找到角色 current”弹窗）
 * 铁律：幂等防抖，已有全局正则绝不重复调用 updateTavernRegexesWith，防止触发 CHAT_CHANGED 重入
 */

const RULE_ID = 'tse-dynamic-sweetener-cleaner';
// 铁律：必须仅吃自身尾随换行，严禁吃前置换行（防止吞掉 </content> 之后的换行符，导致后续 ```<!DOCTYPE html> 粘在同一行被 Markdown 降级为行内 code）
const FIND_PATTERN = '/(?:<tse_meta\\b[\\s\\S]*?<\\/tse_meta>|<tse_meta\\b[^>]*\\/?>)[ \\t]*(?:\\r?\\n|$)/gi';

const CSS_STYLE_ID = 'tse-meta-hidden-style';
const CSS_CONTENT = `
tse_meta,
.tse_meta,
[data-tse-meta] {
  display: none !important;
}
p:has(> tse_meta:only-child) {
  display: none !important;
}
`;

let isGlobalRegexRegistered = false;

/**
 * 注入前台 DOM 辅助隐形样式（作为正则之外的双重辅助防线）
 */
function injectCssGuard() {
  try {
    const doc = (typeof document !== 'undefined') ? document : null;
    if (doc && !doc.getElementById(CSS_STYLE_ID)) {
      const style = doc.createElement('style');
      style.id = CSS_STYLE_ID;
      style.textContent = CSS_CONTENT;
      (doc.head || doc.documentElement).appendChild(style);
      console.log('[TSE Engine] ✔ 已注入前台纯 CSS 静默隐形辅助样式');
    }
  } catch (e) {
    // 静默降级
  }
}

/**
 * 注入前端物理级隐形守卫与宿主正则自举
 * @param {function} getApi API 提取器
 * @param {object} memoryState 引擎内存状态
 */
async function injectCleanerGuard(getApi, memoryState = null) {
  // 铁闸 1: 单实例单次会话只执行一次，彻底杜绝重复重入
  if (isGlobalRegexRegistered) return;

  // 轨 0: 辅助注入 CSS 隐形样式
  injectCssGuard();

  let alreadyConfiguredInMemory = false;

  // 轨 1: 直接向 window.extension_settings.regex 内存挂载 (最纯净、无任何副作用、不重载聊天)
  try {
    const extSettings = (typeof window !== 'undefined' && window.extension_settings) || (typeof global !== 'undefined' && global.extension_settings);
    if (extSettings && Array.isArray(extSettings.regex)) {
      const existing = extSettings.regex.find(r => r.id === RULE_ID || (r.scriptName && r.scriptName.includes('TSE发糖引擎')));
      if (existing) {
        if (existing.findRegex === FIND_PATTERN && !existing.disabled) {
          alreadyConfiguredInMemory = true;
        } else {
          existing.findRegex = FIND_PATTERN;
          existing.disabled = false;
        }
      } else {
        const extRule = {
          id: RULE_ID,
          scriptName: 'TSE发糖引擎·隐藏元数据清洗',
          findRegex: FIND_PATTERN,
          replaceString: '',
          trimStrings: [],
          placement: [2], // 2 = AI 输出
          disabled: false,
          markdownOnly: true, // 仅影响显示 -> 玩家前端绝对不可见
          promptOnly: true,   // 仅影响后端提示词 -> AI 下文不被旧元数据干扰
          runOnEdit: true,
          substituteRegex: 0,
          minDepth: null,
          maxDepth: null
        };
        extSettings.regex.push(extRule);
        console.log('[TSE Engine] ✔ 已向 window.extension_settings.regex 成功直挂全局清洗正则！');
      }
      isGlobalRegexRegistered = true;
    }
  } catch (e) {}

  // 铁闸 2: 内存预检阻断！
  // 铁律：若内存中已有规则且已对齐，绝对禁止调用 updateTavernRegexesWith！
  // 解释：updateTavernRegexesWith 内部无条件触发 render_tavern_regexes_debounced()，
  // 会遍历所有聊天消息调用 refreshOneMessage() 并触发 CHAT_CHANGED，导致状态栏 HUD 发生二次闪烁与重复渲染！
  if (alreadyConfiguredInMemory) {
    return;
  }

  // 轨 2: 仅在全新宿主环境且内存完全未挂载时，才降级通过官方 API 进行一次性对齐
  // ⚠️ 绝不调用 { type: 'character' }，彻底避免“未能找到角色 'current'”红标弹窗！
  const updateRegex = getApi('updateTavernRegexesWith');
  if (typeof updateRegex === 'function') {
    try {
      await updateRegex((regexes) => {
        const existing = regexes.find(r => r.id === RULE_ID || (r.script_name && r.script_name.includes('TSE发糖引擎')));
        if (existing) {
          existing.find_regex = FIND_PATTERN;
          existing.enabled = true;
        } else {
          regexes.push({
            id: RULE_ID,
            script_name: 'TSE发糖引擎·隐藏元数据清洗',
            enabled: true,
            find_regex: FIND_PATTERN,
            replace_string: '',
            trim_strings: [],
            source: {
              user_input: false,
              ai_output: true,
              slash_command: false,
              world_info: false,
              reasoning: false,
            },
            destination: {
              display: true,     // 对应 UI【仅影响显示】
              prompt: true,      // 对应 UI【仅影响后端提示词】
            },
            run_on_edit: true,
            min_depth: null,
            max_depth: null,
          });
        }
        return regexes;
      }, { type: 'global' });
      isGlobalRegexRegistered = true;
    } catch (err) {
      console.warn('[TSE Engine] 全局正则注册微扰:', err);
    }
  }

  // 铁律：严禁使用 $mes.html() 暴力覆写前台已渲染消息！
  // 解释：原生全局正则（markdownOnly: true）已在渲染层静默清洗 <tse_meta>；
  // 若使用 JS 脚本二次覆写 $mes.html()，会瞬间销毁宿主角色卡已挂载的状态栏 iframe 与交互事件。
}

