/**
 * 生成 200x200 原生 SVG 心流动力学雷达图
 * @param {[number, number]} coord 当前 X, Y 坐标
 * @param {string} confirmedQuadrant 当前确认象限
 * @param {Array<string>} activeCardIds 当前活跃卡牌 ID
 */
function renderFlowRadarSvg(coord = [0, 0], confirmedQuadrant = 'Q3', activeCardIds = [], operators = [], activeBuffId = null) {
  const x = (coord && typeof coord[0] === 'number') ? Math.max(-1, Math.min(1, coord[0])) : 0;
  const y = (coord && typeof coord[1] === 'number') ? Math.max(-1, Math.min(1, coord[1])) : 0;
  // 视口 200x200，中心原点 (100, 100)，半径 75
  const svgX = Math.round(100 + x * 75);
  const svgY = Math.round(100 - y * 75);

  const opsToRender = (Array.isArray(operators) && operators.length > 0) ? operators : OPERATORS_DB;
  const operatorNodes = opsToRender.map(op => {
    const ox = (op.anchor && typeof op.anchor[0] === 'number') ? Math.max(-1, Math.min(1, op.anchor[0])) : 0;
    const oy = (op.anchor && typeof op.anchor[1] === 'number') ? Math.max(-1, Math.min(1, op.anchor[1])) : 0;
    const cx = Math.round(100 + ox * 75);
    const cy = Math.round(100 - oy * 75);

    let color = '#f472b6'; // sweet 粉色
    let flavorLabel = '蜜糖';
    if (op.flavor === 'spicy') {
      color = '#fb923c'; // spicy 橙红
      flavorLabel = '劲辣';
    } else if (op.flavor === 'custom') {
      color = '#38bdf8'; // custom 天蓝
      flavorLabel = '定制';
    }

    const isActiveBuff = activeBuffId && op.id === activeBuffId;
    const isHand = Array.isArray(activeCardIds) && activeCardIds.includes(op.id);

    if (isActiveBuff) {
      // 正在生效的在场卡牌：金色呼吸光环 + 放大高亮
      return `
        <g>
          <circle cx="${cx}" cy="${cy}" r="8" fill="none" stroke="#facc15" stroke-width="1.8" opacity="0.9">
            <animate attributeName="r" values="6;13;6" dur="1.8s" repeatCount="indefinite" />
            <animate attributeName="opacity" values="1;0.2;1" dur="1.8s" repeatCount="indefinite" />
          </circle>
          <circle cx="${cx}" cy="${cy}" r="4.8" fill="#facc15" stroke="#ffffff" stroke-width="1.5">
            <title>【当前在场生效】[${flavorLabel}] ${op.id}: ${op.name} (${op.quadrant})</title>
          </circle>
        </g>
      `;
    }

    if (isHand) {
      // 手牌中的卡牌：清晰白边 + 半径 3.8
      return `
        <circle cx="${cx}" cy="${cy}" r="3.8" fill="${color}" stroke="#ffffff" stroke-width="1.2" opacity="0.95">
          <title>[手牌] [${flavorLabel}] ${op.id}: ${op.name} (${op.quadrant})</title>
        </circle>
      `;
    }

    // 牌库中未抽到的卡牌：轻微半透明 + 半径 2.6
    return `
      <circle cx="${cx}" cy="${cy}" r="2.6" fill="${color}" stroke="#ffffff" stroke-width="0.6" opacity="0.45">
        <title>[牌库] [${flavorLabel}] ${op.id}: ${op.name} (${op.quadrant})</title>
      </circle>
    `;
  }).join('');

  return `
    <svg viewBox="0 0 200 200" style="width:185px;height:185px;max-width:100%;aspect-ratio:1/1;display:block;margin:0 auto;filter:drop-shadow(0 0 10px rgba(56,189,248,0.25));">
      <defs>
        <radialGradient id="tse_q1" cx="70%" cy="30%" r="70%">
          <stop offset="0%" stop-color="#f472b6" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#f472b6" stop-opacity="0.03"/>
        </radialGradient>
        <radialGradient id="tse_q2" cx="30%" cy="30%" r="70%">
          <stop offset="0%" stop-color="#c084fc" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#c084fc" stop-opacity="0.03"/>
        </radialGradient>
        <radialGradient id="tse_q3" cx="30%" cy="70%" r="70%">
          <stop offset="0%" stop-color="#38bdf8" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#38bdf8" stop-opacity="0.03"/>
        </radialGradient>
        <radialGradient id="tse_q4" cx="70%" cy="70%" r="70%">
          <stop offset="0%" stop-color="#4ade80" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#4ade80" stop-opacity="0.03"/>
        </radialGradient>
        <filter id="tse_text_glow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="1" stdDeviation="1.5" flood-color="#000000" flood-opacity="0.9"/>
        </filter>
      </defs>

      <!-- 4 象限底色色域 -->
      <rect x="100" y="25" width="75" height="75" fill="url(#tse_q1)" rx="4"/>
      <rect x="25" y="25" width="75" height="75" fill="url(#tse_q2)" rx="4"/>
      <rect x="25" y="100" width="75" height="75" fill="url(#tse_q3)" rx="4"/>
      <rect x="100" y="100" width="75" height="75" fill="url(#tse_q4)" rx="4"/>

      <!-- 同心圆刻度 -->
      <circle cx="100" cy="100" r="75" fill="none" stroke="rgba(255,255,255,0.18)" stroke-width="1.2"/>
      <circle cx="100" cy="100" r="50" fill="none" stroke="rgba(255,255,255,0.1)" stroke-dasharray="3,3"/>
      <circle cx="100" cy="100" r="25" fill="none" stroke="rgba(255,255,255,0.08)" stroke-dasharray="2,2"/>

