      <!-- 动态呼吸光标 (当前坐标) -->
      <g transform="translate(${svgX}, ${svgY})">
        <circle cx="0" cy="0" r="10" fill="none" stroke="#38bdf8" stroke-width="2" opacity="0.9">
          <animate attributeName="r" values="6;16;6" dur="2.2s" repeatCount="indefinite" />
          <animate attributeName="opacity" values="0.95;0.15;0.95" dur="2.2s" repeatCount="indefinite" />
        </circle>
        <circle cx="0" cy="0" r="4.5" fill="#38bdf8" stroke="#ffffff" stroke-width="1.2" />
      </g>
    </svg>
  `;
}

class TseHUD {
  constructor(engine) {
    this.engine = engine;
    this.isOpen = false;
    this.activeTab = 'tab-flow'; // 'tab-flow' | 'tab-status' | 'tab-ops' | 'tab-prompts'
    this.promptSubTab = 'd1';    // 'd1' | 'd0'
    this.selectedOpId = 'A1';
    this.ballEl = null;
    this.modalEl = null;
    this.ballVisibleState = null;
    this._hotkeyHandler = null;
  }

  isBallVisible() {
    if (typeof this.ballVisibleState === 'boolean') {
      return this.ballVisibleState;
    }

    // 1. 终极保险总开关：直接读取酒馆助手脚本配置 (图1 界面绑定的真值来源)
    try {
      const p = (typeof window !== 'undefined' && window.parent) ? window.parent : (typeof window !== 'undefined' ? window : globalThis);
      const getContext = p.SillyTavern?.getContext || (typeof SillyTavern !== 'undefined' ? SillyTavern.getContext : null);
      const ctx = (typeof getContext === 'function') ? getContext() : null;
      const extSettings = ctx?.extensionSettings || p.extension_settings || (typeof global !== 'undefined' ? global.extension_settings : null);
      const scripts = extSettings?.tavern_helper?.script?.scripts;
      if (Array.isArray(scripts)) {
        const me = scripts.find(s => s.id === 'tse-dynamic-sweetener-engine' || (s.name && (s.name.includes('TSE') || s.name.includes('发糖'))));
        if (me && me.data && typeof me.data.show_floating_ball === 'boolean') {
          this.ballVisibleState = me.data.show_floating_ball;
          return this.ballVisibleState;
        }
      }
    } catch (e) {}

    // 2. 从 TavernHelper 变量 API 中读取
    try {
      const getVars = (typeof window !== 'undefined' && typeof window.getVariables === 'function') ? window.getVariables : this.engine?.getApi('getVariables');
      if (typeof getVars === 'function') {
        const sVars = getVars({ type: 'script' });
        if (sVars && typeof sVars.show_floating_ball === 'boolean') {
          this.ballVisibleState = sVars.show_floating_ball;
          return this.ballVisibleState;
        }
      }
    } catch (e) {}

    try {
      const getAllVars = (typeof window !== 'undefined' && typeof window.getAllVariables === 'function') ? window.getAllVariables : this.engine?.getApi('getAllVariables');
      if (typeof getAllVars === 'function') {
        const all = getAllVars();
        if (all && typeof all.show_floating_ball === 'boolean') {
          this.ballVisibleState = all.show_floating_ball;
          return this.ballVisibleState;
        }
      }
    } catch (e) {}

    if (this.engine?.context?.data && typeof this.engine.context.data.show_floating_ball === 'boolean') {
      this.ballVisibleState = this.engine.context.data.show_floating_ball;
      return this.ballVisibleState;
    }

    // 终极保底：默认为 true，绝不遗失悬浮球
    this.ballVisibleState = true;
    return true;
  }

  setBallVisible(visible) {
    this.ballVisibleState = !!visible;

    // 1. 同步修改酒馆助手 live store 配置（使图1 界面实时同步更新）
    try {
      const p = (typeof window !== 'undefined' && window.parent) ? window.parent : (typeof window !== 'undefined' ? window : globalThis);
      const getContext = p.SillyTavern?.getContext || (typeof SillyTavern !== 'undefined' ? SillyTavern.getContext : null);
      const ctx = (typeof getContext === 'function') ? getContext() : null;
      const extSettings = ctx?.extensionSettings || p.extension_settings || (typeof global !== 'undefined' ? global.extension_settings : null);
      const scripts = extSettings?.tavern_helper?.script?.scripts;
      if (Array.isArray(scripts)) {
        const me = scripts.find(s => s.id === 'tse-dynamic-sweetener-engine' || (s.name && (s.name.includes('TSE') || s.name.includes('发糖'))));
        if (me) {
          if (!me.data || typeof me.data !== 'object') me.data = {};
          me.data.show_floating_ball = !!visible;
        }
      }
      const saveSettings = p.saveSettingsDebounced || ctx?.saveSettingsDebounced;
      if (typeof saveSettings === 'function') saveSettings();
    } catch (e) {}

    // 2. 同步 TavernHelper 脚本变量
    try {
      const updateVars = (typeof window !== 'undefined' && typeof window.updateVariablesWith === 'function') ? window.updateVariablesWith : this.engine?.getApi('updateVariablesWith');
      if (typeof updateVars === 'function') {
        updateVars((vars) => {
          vars.show_floating_ball = !!visible;
          return vars;
        }, { type: 'script' });
      }
    } catch (e) {}

    if (this.engine?.context?.data) {
      this.engine.context.data.show_floating_ball = !!visible;
    }

    // 彻底清除历史 localStorage 遗留脏数据，杜绝死锁
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.removeItem('tse_floating_ball_visible');
      }
    } catch (e) {}

    if (this.ballEl) {
      this.ballEl.style.display = visible ? 'flex' : 'none';
    }
    this.render();
  }

  getTopDoc() {
    try {
      if (typeof window !== 'undefined' && window.parent && window.parent.document && window.parent.document.body) {
        return window.parent.document;
      }
    } catch (e) {}
    return (typeof document !== 'undefined') ? document : null;
  }

  mount() {
    const doc = this.getTopDoc();
    if (!doc) return;

    this.unmount();

    // 每次重新 mount (脚本重启/开关时)，重置内存缓存，确保读取图1最新配置
    this.ballVisibleState = null;

    // 清理历史可能残留的 localStorage 脏数据
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.removeItem('tse_floating_ball_visible');
      }
    } catch (e) {}

    // 1. 创建悬浮球
    const ball = doc.createElement('div');
    ball.id = 'tse-floating-ball';
    ball.title = 'TSE 动态发糖卡牌引擎控制台 (点击展开/收起，可任意拖动 · Alt+T)';
    ball.innerHTML = `<span>🍬</span><span style="margin-left:2px;font-size:11px;font-weight:700;">TSE</span>`;

    // 立即通过保险总开关读取显隐状态
    const isBallShown = this.isBallVisible();

    ball.style.cssText = `
      position: fixed;
      bottom: 85px;
      right: 20px;
      width: 48px;
      height: 48px;
      border-radius: 24px;
      background: linear-gradient(135deg, #ec4899 0%, #8b5cf6 100%);
      box-shadow: 0 4px 14px rgba(236, 72, 153, 0.45);
      color: #ffffff;
      display: ${isBallShown ? 'flex' : 'none'};
      align-items: center;
      justify-content: center;
      cursor: pointer;
      z-index: 999998;
      user-select: none;
      touch-action: none;
      -webkit-tap-highlight-color: transparent;
      transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s;
    `;
    ball.style.display = isBallShown ? 'flex' : 'none';
    ball.onmouseenter = () => { ball.style.transform = 'scale(1.1)'; };
    ball.onmouseleave = () => { ball.style.transform = 'scale(1.0)'; };

    // 悬浮球拖拽逻辑（区分拖动与点击）
    this.setupBallDraggable(ball, doc);

    // 2. 创建主弹窗容器 (大小自由 + 可拖出屏幕)
    const modal = doc.createElement('div');
    modal.id = 'tse-hud-modal';

    const GOLDEN_WIDTH = '620px';
    const GOLDEN_HEIGHT = '560px';

    let savedPos = null;
    try {
      if (typeof localStorage !== 'undefined') {
        const raw = localStorage.getItem('tse_hud_pos_v2') || localStorage.getItem('tse_hud_pos');
        if (raw) {
          savedPos = JSON.parse(raw);
          // 智能平滑升级：若为旧版的 540px 高度或 580/600px 宽度，自动升级为全新的 620px 黄金无折行尺寸
          const hVal = parseInt(savedPos.height, 10);
          if (isNaN(hVal) || hVal <= 545 || savedPos.height === '540px') {
            savedPos.height = GOLDEN_HEIGHT;
          }
          const wVal = parseInt(savedPos.width, 10);
          if (isNaN(wVal) || wVal <= 605 || savedPos.width === '580px' || savedPos.width === '600px') {
            savedPos.width = GOLDEN_WIDTH;
          }
        }
      }
    } catch (e) {}

    const initLeft = savedPos?.left || 'auto';
    const initTop = savedPos?.top || '100px';
    const initRight = savedPos?.left ? 'auto' : '24px';
    const initBottom = 'auto';
    const initWidth = savedPos?.width || GOLDEN_WIDTH;
    const initHeight = savedPos?.height || GOLDEN_HEIGHT;

    modal.style.cssText = `
      position: fixed;
      top: ${initTop};
      left: ${initLeft};
      right: ${initRight};
      bottom: ${initBottom};
      width: ${initWidth};
      height: ${initHeight};
      min-width: 360px;
      min-height: 380px;
      max-width: none;
      max-height: none;
      background: rgba(20, 22, 28, 0.96);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 14px;
      box-shadow: 0 20px 48px rgba(0, 0, 0, 0.7);
      color: #e2e8f0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      font-size: 13px;
      line-height: 1.5;
      z-index: 999999;
      display: none;
      flex-direction: column;
      overflow: hidden;
      resize: both;
      box-sizing: border-box;
      animation: tseFadeIn 0.2s ease-out;
    `;
    modal.style.resize = 'both';
    modal.style.width = initWidth;
    modal.style.height = initHeight;

    doc.body.appendChild(ball);
    doc.body.appendChild(modal);

    this.ballEl = ball;
    this.modalEl = modal;

    // 挂载全局快捷键 Alt + T 呼出/关闭控制台，Esc 平滑关闭
    if (!this._hotkeyHandler) {
      this._hotkeyHandler = (e) => {
        if (e.altKey && (e.key === 't' || e.key === 'T')) {
          e.preventDefault();
          this.toggle();
        } else if (e.key === 'Escape' && this.isOpen) {
          e.preventDefault();
          this.close();
        }
      };
      if (doc && typeof doc.addEventListener === 'function') {
        doc.addEventListener('keydown', this._hotkeyHandler);
      }
      if (typeof window !== 'undefined' && window !== doc?.defaultView && typeof window.addEventListener === 'function') {
        window.addEventListener('keydown', this._hotkeyHandler);
      }
    }

    // 挂载酒馆魔术棒扩展菜单项
    this.mountWandMenuEntry();

    this.render();
  }

  setupBallDraggable(ball, doc) {
    if (!ball || typeof ball.addEventListener !== 'function') return;
    let isDragging = false;
    let hasMoved = false;
    let startX = 0, startY = 0;
    let initLeft = 0, initTop = 0;

    ball.style.touchAction = 'none';

    const onPointerDown = (e) => {
      if (e.button !== undefined && e.button !== 0) return;
      isDragging = true;
      hasMoved = false;
      startX = e.clientX;
      startY = e.clientY;
      const rect = ball.getBoundingClientRect ? ball.getBoundingClientRect() : { left: 0, top: 0 };
      initLeft = rect.left;
      initTop = rect.top;

      ball.style.left = initLeft + 'px';
      ball.style.top = initTop + 'px';
      ball.style.bottom = 'auto';
      ball.style.right = 'auto';

      if (typeof ball.setPointerCapture === 'function' && e.pointerId !== undefined) {
        try { ball.setPointerCapture(e.pointerId); } catch (err) {}
      }

      const onPointerMove = (ev) => {
        if (!isDragging) return;
        const dx = ev.clientX - startX;
        const dy = ev.clientY - startY;
        if (Math.abs(dx) > 4 || Math.abs(dy) > 4) {
          hasMoved = true;
        }
        ball.style.left = (initLeft + dx) + 'px';
        ball.style.top = (initTop + dy) + 'px';
      };

      const onPointerUp = (ev) => {
        if (!isDragging) return;
        isDragging = false;
        if (typeof ball.releasePointerCapture === 'function' && ev && ev.pointerId !== undefined) {
          try { ball.releasePointerCapture(ev.pointerId); } catch (err) {}
        }
        if (doc && typeof doc.removeEventListener === 'function') {
          doc.removeEventListener('pointermove', onPointerMove);
          doc.removeEventListener('pointerup', onPointerUp);
          doc.removeEventListener('pointercancel', onPointerUp);
          doc.removeEventListener('mousemove', onPointerMove);
          doc.removeEventListener('mouseup', onPointerUp);
        }
        if (typeof ball.removeEventListener === 'function') {
          ball.removeEventListener('pointermove', onPointerMove);
          ball.removeEventListener('pointerup', onPointerUp);
          ball.removeEventListener('pointercancel', onPointerUp);
        }
      };

      if (typeof ball.addEventListener === 'function') {
        ball.addEventListener('pointermove', onPointerMove);
        ball.addEventListener('pointerup', onPointerUp);
        ball.addEventListener('pointercancel', onPointerUp);
      }
      if (doc && typeof doc.addEventListener === 'function') {
        doc.addEventListener('pointermove', onPointerMove);
        doc.addEventListener('pointerup', onPointerUp);
        doc.addEventListener('pointercancel', onPointerUp);
        doc.addEventListener('mousemove', onPointerMove);
        doc.addEventListener('mouseup', onPointerUp);
      }
    };

    ball.addEventListener('pointerdown', onPointerDown);
    ball.addEventListener('mousedown', onPointerDown);

    ball.onclick = (e) => {
      e.stopPropagation();
      if (hasMoved) return; // 拖动完成后不触发展开/收起
      this.toggle();
    };
  }

  setupModalDraggable(handleEl, targetEl) {
    if (!handleEl || !targetEl || typeof handleEl.addEventListener !== 'function') return;

    handleEl.style.cursor = 'grab';
    handleEl.style.touchAction = 'none';

    const onPointerDown = (e) => {
      if (e.target && typeof e.target.closest === 'function' && e.target.closest('button, input, select, textarea, .tse-no-drag, #tse-hud-close')) {
        return;
      }
      if (e.button !== undefined && e.button !== 0) return;

      let isDragging = true;
      handleEl.style.cursor = 'grabbing';
      const startX = e.clientX;
      const startY = e.clientY;

      let rect = { left: 0, top: 0 };
      if (typeof targetEl.getBoundingClientRect === 'function') {
        rect = targetEl.getBoundingClientRect();
      }
      const initialLeft = rect.left;
      const initialTop = rect.top;

      targetEl.style.left = initialLeft + 'px';
      targetEl.style.top = initialTop + 'px';
      targetEl.style.bottom = 'auto';
      targetEl.style.right = 'auto';

      const doc = this.getTopDoc() || (typeof document !== 'undefined' ? document : null);
      if (!doc || typeof doc.addEventListener !== 'function') return;

      if (typeof handleEl.setPointerCapture === 'function' && e.pointerId !== undefined) {
        try { handleEl.setPointerCapture(e.pointerId); } catch (err) {}
      }

      const onPointerMove = (ev) => {
        if (!isDragging) return;
        const dx = ev.clientX - startX;
        const dy = ev.clientY - startY;

        let newLeft = initialLeft + dx;
        let newTop = initialTop + dy;

        // 允许拖出屏幕！只保留最小 40px 的头部留在视口内防彻底遗失
        const winW = (doc.defaultView || (typeof window !== 'undefined' ? window : {})).innerWidth || 1280;
        const winH = (doc.defaultView || (typeof window !== 'undefined' ? window : {})).innerHeight || 800;
        const minVisible = 40;
        const targetW = targetEl.offsetWidth || 500;

        // 移动端安全护栏：若屏幕较窄 (<= 640px)，防止被完全甩出视野找不到
        if (winW <= 640) {
          newLeft = Math.max(-targetW + 80, Math.min(winW - 80, newLeft));
          newTop = Math.max(0, Math.min(winH - 50, newTop));
        } else {
          newLeft = Math.max(-targetW + minVisible, Math.min(winW - minVisible, newLeft));
          newTop = Math.max(0, Math.min(winH - minVisible, newTop));
        }

        targetEl.style.left = Math.round(newLeft) + 'px';
        targetEl.style.top = Math.round(newTop) + 'px';
      };

      const onPointerUp = (ev) => {
        if (!isDragging) return;
        isDragging = false;
        handleEl.style.cursor = 'grab';

        if (typeof handleEl.releasePointerCapture === 'function' && ev && ev.pointerId !== undefined) {
          try { handleEl.releasePointerCapture(ev.pointerId); } catch (err) {}
        }

        if (doc && typeof doc.removeEventListener === 'function') {
          doc.removeEventListener('pointermove', onPointerMove);
          doc.removeEventListener('pointerup', onPointerUp);
          doc.removeEventListener('pointercancel', onPointerUp);
          doc.removeEventListener('mousemove', onPointerMove);
          doc.removeEventListener('mouseup', onPointerUp);
        }
        if (typeof handleEl.removeEventListener === 'function') {
          handleEl.removeEventListener('pointermove', onPointerMove);
          handleEl.removeEventListener('pointerup', onPointerUp);
          handleEl.removeEventListener('pointercancel', onPointerUp);
        }

        try {
          if (typeof localStorage !== 'undefined') {
            const posPayload = JSON.stringify({
              left: targetEl.style.left,
              top: targetEl.style.top,
              width: targetEl.style.width,
              height: targetEl.style.height
            });
            localStorage.setItem('tse_hud_pos_v2', posPayload);
            localStorage.setItem('tse_hud_pos', posPayload);
          }
        } catch (err) {}
      };

      if (typeof handleEl.addEventListener === 'function') {
        handleEl.addEventListener('pointermove', onPointerMove);
        handleEl.addEventListener('pointerup', onPointerUp);
        handleEl.addEventListener('pointercancel', onPointerUp);
      }
      doc.addEventListener('pointermove', onPointerMove);
      doc.addEventListener('pointerup', onPointerUp);
      doc.addEventListener('pointercancel', onPointerUp);
      doc.addEventListener('mousemove', onPointerMove);
      doc.addEventListener('mouseup', onPointerUp);
    };

    handleEl.addEventListener('pointerdown', onPointerDown);
    handleEl.addEventListener('mousedown', onPointerDown);
  }

  toggle() {
    this.isOpen = !this.isOpen;
    if (this.modalEl) {
      this.modalEl.style.display = this.isOpen ? 'flex' : 'none';
      if (this.isOpen) {
        this.render();
      }
    }
  }

  close() {
    this.isOpen = false;
    if (this.modalEl) {
      this.modalEl.style.display = 'none';
    }
  }

  unmount() {
    const doc = this.getTopDoc();
    if (!doc) return;
    const oldBall = doc.getElementById('tse-floating-ball');
    if (oldBall) oldBall.remove();
    const oldModal = doc.getElementById('tse-hud-modal');
    if (oldModal) oldModal.remove();
    const oldWandEntry = doc.getElementById('tse-wand-menu-entry');
    if (oldWandEntry) oldWandEntry.remove();
    this.ballEl = null;
    this.modalEl = null;
    this.isOpen = false;
    if (this._hotkeyHandler) {
      if (doc && typeof doc.removeEventListener === 'function') {
        doc.removeEventListener('keydown', this._hotkeyHandler);
      }
      if (typeof window !== 'undefined' && window !== doc?.defaultView && typeof window.removeEventListener === 'function') {
        window.removeEventListener('keydown', this._hotkeyHandler);
      }
      this._hotkeyHandler = null;
    }
  }

  getWandMenuHost(doc) {
    const d = doc || this.getTopDoc();
    if (!d) return null;
    return d.getElementById('extensionsMenu') || d.getElementById('top-settings-holder') || null;
  }

  createWandMenuEntry(doc) {
    const entry = doc.createElement('div');
    entry.id = 'tse-wand-menu-entry';
    entry.className = 'extension_container interactable tse-no-drag';
    entry.title = '🍬 TSE发糖引擎控制台 (Alt+T)';
    entry.setAttribute('role', 'button');
    entry.setAttribute('aria-label', '🍬 TSE控制台');
    entry.tabIndex = 0;
    entry.style.cssText = 'order: 999;';

    const row = doc.createElement('div');
    row.id = 'tse-wand-menu-row';
    row.className = 'list-group-item flex-container flexGap5 interactable';
    row.setAttribute('role', 'listitem');
    row.tabIndex = 0;
    row.title = '🍬 TSE发糖引擎控制台 (Alt+T)';
    row.style.cssText = 'cursor: pointer; user-select: none; display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 4px; transition: background 0.15s;';

    const icon = doc.createElement('div');
    icon.className = 'fa-fw fa-solid fa-candy-cane extensionsMenuExtensionButton';
    icon.style.cssText = 'color: #ec4899; font-size: 14px; display: inline-flex; align-items: center; justify-content: center; min-width: 18px; line-height: 1;';
    icon.textContent = '🍬';

    const label = doc.createElement('span');
    label.className = 'tse-wand-menu-label';
    label.textContent = '🍬 TSE控制台';
    label.style.cssText = 'font-size: 13px; font-weight: 500; color: inherit; white-space: nowrap;';

    row.append(icon, label);
    entry.appendChild(row);

    const handleToggle = (e) => {
      if (e) {
        if (typeof e.preventDefault === 'function') e.preventDefault();
        if (typeof e.stopPropagation === 'function') e.stopPropagation();
      }
      this.toggle();
    };

    entry.addEventListener('click', handleToggle);
    row.addEventListener('click', handleToggle);
    entry.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') handleToggle(e);
    });
    row.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') handleToggle(e);
    });

    return entry;
  }

  mountWandMenuEntry() {
    const doc = this.getTopDoc();
    if (!doc) return false;
    const host = this.getWandMenuHost(doc);
    if (!host) {
      this.watchWandMenuButton(doc);
      return false;
    }

    let entry = doc.getElementById('tse-wand-menu-entry');
    if (!entry) {
      entry = this.createWandMenuEntry(doc);
    }

    if (entry.parentElement !== host) {
      host.appendChild(entry);
    }

    this.watchWandMenuButton(doc);
    return true;
  }

  watchWandMenuButton(doc) {
    if (!doc) return;
    const btn = doc.getElementById('extensionsMenuButton');
    if (!btn || btn.dataset.tseWandBound === 'true') return;
    btn.dataset.tseWandBound = 'true';
    btn.addEventListener('click', () => {
      setTimeout(() => this.mountWandMenuEntry(), 0);
      setTimeout(() => this.mountWandMenuEntry(), 150);
    });
  }

  render() {
    if (!this.modalEl) return;

    const state = this.engine.getState();
    const actualFloor = (typeof this.engine.getActualChatFloor === 'function') ? this.engine.getActualChatFloor() : -1;
    const getLastId = this.engine.getApi('getLastMessageId');
    const currentFloor = actualFloor >= 0 ? actualFloor : ((typeof getLastId === 'function') ? getLastId() : (this.engine.lastHandledFloor ?? 0));
    const floorStatus = formatHumanReadableFloorStatus(state, currentFloor);

    // 选项卡标签定义
    const tabs = [
      { id: 'tab-flow', label: '📊 心流象限' },
      { id: 'tab-status', label: '🎴 抽牌追踪' },
      { id: 'tab-ops', label: '🎨 风味工坊' },
      { id: 'tab-prompts', label: '📝 提示词模板' },
    ];

    const tabNavHtml = tabs.map(t => {
      const activeStyle = (this.activeTab === t.id)
