    // -------------------------------------------------------------
    else if (this.activeTab === 'tab-status') {
      const settings = state.settings || {};
      const duration = (typeof settings.sweet_duration === 'number') ? settings.sweet_duration : 2;
      const cooldown = (typeof settings.sweet_cooldown === 'number') ? settings.sweet_cooldown : 1;

      const badgeColors = {
