      // 构造当前就绪手牌池 (In-Hand Cards) 视觉卡片与大牌库轮替状态
      const handCards = Array.isArray(state.hand) ? state.hand : [];
      const totalOps = getEffectiveOperators(state.custom_operators || {}, state.active_flavors || ['sweet', 'spicy'], state.custom_deck || []);
      const deadIds = new Set(Array.isArray(state.graveyard) ? state.graveyard : []);
      const unplayedDeckCount = totalOps.filter(o => !deadIds.has(o.id)).length;
