              <textarea id="tse-input-d0-template" rows="12" style="width:100%;box-sizing:border-box;padding:8px 10px;background:#0f172a;border:1px solid rgba(255,255,255,0.12);border-radius:6px;color:#f1f5f9;font-family:monospace;font-size:11px;line-height:1.45;resize:vertical;outline:none;">${currentD0Template}</textarea>
