    }

    const isBallShown = this.isBallVisible();
    const ballBtnStyle = isBallShown
      ? 'background:rgba(236,72,153,0.12);border:1px solid rgba(236,72,153,0.3);color:#f472b6;padding:3px 8px;border-radius:4px;font-size:11px;cursor:pointer;display:flex;align-items:center;gap:3px;white-space:nowrap;flex-shrink:0;'
