        <button type="button" class="tse-no-drag" id="tse-hud-bottom-close-btn" style="width:100%;padding:9px 12px;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.18);border-radius:6px;color:#f1f5f9;font-size:12px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;-webkit-tap-highlight-color:transparent;">
          <span>✕</span><span>收起控制台</span>
        </button>
