  showToast(text = '✔ 保存成功并已实时生效！') {
    if (!this.modalEl) return;
    const toast = this.modalEl.querySelector('#tse-hud-toast');
    if (toast) {
      toast.textContent = text;
      toast.style.display = 'block';
      setTimeout(() => { toast.style.display = 'none'; }, 2000);
    }
  }

  bindEvents() {
    if (!this.modalEl) return;

    // 绑定拖拽
    const header = this.modalEl.querySelector('#tse-hud-header');
    if (header) {
      this.setupModalDraggable(header, this.modalEl);
    }

    // 切换右下角悬浮球彻底显隐
    const toggleBallBtn = this.modalEl.querySelector('#tse-hud-toggle-ball-btn');
    if (toggleBallBtn) {
      toggleBallBtn.onclick = () => {
        const nextVisible = !this.isBallVisible();
        this.setBallVisible(nextVisible);
        if (nextVisible) {
          this.showToast('✔ 悬浮球已恢复显示！');
        } else {
          this.showToast('✔ 悬浮球已彻底隐藏！随时按 Alt+T 唤回，或在脚本设置中重新开关。');
        }
      };
    }

    // 复位位置按钮
    const resetPosBtn = this.modalEl.querySelector('#tse-hud-reset-pos-btn');
    if (resetPosBtn) {
      resetPosBtn.onclick = () => {
        this.modalEl.style.top = '100px';
        this.modalEl.style.left = 'auto';
        this.modalEl.style.right = '24px';
        this.modalEl.style.bottom = 'auto';
        this.modalEl.style.width = '600px';
        this.modalEl.style.height = '560px';
        try {
          if (typeof localStorage !== 'undefined') {
            localStorage.removeItem('tse_hud_pos');
            localStorage.removeItem('tse_hud_pos_v2');
          }
        } catch (e) {}
        this.showToast('✔ 控制台位置与大小已复位！');
      };
    }

    // 关闭按钮 (彻底隔离 pointer/touch 事件，防止被父级拖拽捕获拦截)
    const closeBtn = this.modalEl.querySelector('#tse-hud-close');
    if (closeBtn) {
      const handleClose = (e) => {
        if (e) {
          if (typeof e.preventDefault === 'function') e.preventDefault();
          if (typeof e.stopPropagation === 'function') e.stopPropagation();
        }
        this.close();
      };
      closeBtn.addEventListener('pointerdown', (e) => e.stopPropagation());
      closeBtn.addEventListener('mousedown', (e) => e.stopPropagation());
      closeBtn.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });
      closeBtn.onclick = handleClose;
    }

    // 移动端底部快捷收起按钮
    const bottomCloseBtn = this.modalEl.querySelector('#tse-hud-bottom-close-btn');
    if (bottomCloseBtn) {
      const handleBottomClose = (e) => {
        if (e) {
          if (typeof e.preventDefault === 'function') e.preventDefault();
          if (typeof e.stopPropagation === 'function') e.stopPropagation();
        }
        this.close();
      };
      bottomCloseBtn.addEventListener('pointerdown', (e) => e.stopPropagation());
      bottomCloseBtn.addEventListener('mousedown', (e) => e.stopPropagation());
      bottomCloseBtn.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });
      bottomCloseBtn.onclick = handleBottomClose;
    }

    // 一键重置当前对话状态按钮
    const resetBtn = this.modalEl.querySelector('#tse-hud-reset-btn');
    if (resetBtn) {
      resetBtn.onclick = async () => {
        const confirmed = (typeof globalThis.confirm === 'function')
          ? globalThis.confirm('确定要清空本对话的所有发糖状态、楼层计数与DMP画像吗？\n（将恢复为绝对纯净的初始白板，可彻底清除历史残留）')
          : true;
        if (confirmed) {
          await this.engine.resetCurrentChatState();
          this.showToast('✔ 本对话发糖状态已清空重置为初始白板！');
        }
      };
    }

    // 清空重置 DMP 角色好感度与羁绊按钮
    const clearDmpBtn = this.modalEl.querySelector('#tse-btn-clear-dmp');
    if (clearDmpBtn) {
      clearDmpBtn.onclick = async () => {
        const confirmed = (typeof globalThis.confirm === 'function')
          ? globalThis.confirm('确定要清空全部角色的好感度记录与近期羁绊数据吗？\n（将重置历史总榜与近期 10 回合焦点，开始全新攻略篇章）')
          : true;
        if (confirmed) {
          await this.engine.clearDmpData();
          this.showToast('✔ 已清空全部角色好感度记录与近期焦点！');
        }
      };
    }

    // 标签切换
    const tabBtns = this.modalEl.querySelectorAll('.tse-tab-btn');
    tabBtns.forEach(btn => {
      btn.onclick = () => {
        this.activeTab = btn.getAttribute('data-tab');
        this.render();
      };
    });

    // 1. 风味勾选框切换 (支持多选混编)
    const chkSweet = this.modalEl.querySelector('#tse-chk-flavor-sweet');
    const chkSpicy = this.modalEl.querySelector('#tse-chk-flavor-spicy');
    const chkCustom = this.modalEl.querySelector('#tse-chk-flavor-custom');

    const updateFlavorsFromUi = async () => {
      const selectedFlavors = [];
      if (chkSweet && chkSweet.checked) selectedFlavors.push('sweet');
      if (chkSpicy && chkSpicy.checked) selectedFlavors.push('spicy');
      if (chkCustom && chkCustom.checked) selectedFlavors.push('custom');
      if (selectedFlavors.length === 0) {
        if (chkSweet) chkSweet.checked = true;
        selectedFlavors.push('sweet');
      }
      await this.engine.setActiveFlavors(selectedFlavors);
      this.showToast(`✔ 已应用风味配置: ${selectedFlavors.join(' + ')}`);
      this.render();
    };

    if (chkSweet) chkSweet.onchange = updateFlavorsFromUi;
    if (chkSpicy) chkSpicy.onchange = updateFlavorsFromUi;
    if (chkCustom) chkCustom.onchange = updateFlavorsFromUi;

    // 2. 超时保护输入与持久化保存
    const inputTimeout = this.modalEl.querySelector('#tse-input-generator-timeout');
    if (inputTimeout) {
      inputTimeout.onchange = async () => {
        const val = parseInt(inputTimeout.value, 10);
        if (!isNaN(val) && val >= 10 && val <= 1800) {
          const st = this.engine.getState();
          if (!st.settings) st.settings = {};
          st.settings.generator_timeout = val;
          await this.engine.saveState();
          this.showToast(`⏱️ 超时保护已设置为 ${val} 秒并保存`);
        } else {
          inputTimeout.value = this.engine.getState().settings?.generator_timeout || 240;
        }
      };
    }

    // 2.1 小机器人异步生成专属 12 算子（含动态秒级心跳计时）
    const btnGenDeck = this.modalEl.querySelector('#tse-btn-generate-deck');
    if (btnGenDeck) {
      btnGenDeck.onclick = async () => {
        const inputWish = this.modalEl.querySelector('#tse-input-generator-wish');
        const statusDiv = this.modalEl.querySelector('#tse-generator-status');
        const wish = inputWish ? inputWish.value.trim() : '';

        // 读取输入的超时值，如有变化顺手持久化
        let timeoutSec = this.engine.getState().settings?.generator_timeout || 240;
        if (inputTimeout) {
          const parsed = parseInt(inputTimeout.value, 10);
          if (!isNaN(parsed) && parsed >= 10 && parsed <= 1800) {
            timeoutSec = parsed;
            const st = this.engine.getState();
            if (st.settings && st.settings.generator_timeout !== parsed) {
              st.settings.generator_timeout = parsed;
              await this.engine.saveState();
            }
          }
        }

        let currentPhase = '🚀 正在启动纯净沙盒生成器...';
        let elapsedSec = 0;

        const renderDynamicStatus = () => {
          if (statusDiv) {
            statusDiv.textContent = `${currentPhase} (${elapsedSec}s / ${timeoutSec}s)`;
          }
        };

        if (statusDiv) {
          statusDiv.style.display = 'block';
          statusDiv.style.color = '#38bdf8';
          renderDynamicStatus();
        }
        btnGenDeck.disabled = true;
        btnGenDeck.style.opacity = '0.6';

        // 动态秒级心跳更新
        let timerId = setInterval(() => {
          elapsedSec++;
          renderDynamicStatus();
        }, 1000);

        try {
          const genFunc = (typeof generateCustomDeckAsync === 'function')
            ? generateCustomDeckAsync
            : (this.engine.ctx?.generateCustomDeckAsync || null);

          if (!genFunc) {
            throw new Error('未加载 flavor_generator 生成器模块');
          }

          const deck = await genFunc(
            wish,
            this.engine.getApi.bind(this.engine),
            (statusText) => {
              currentPhase = statusText;
              renderDynamicStatus();
            },
            timeoutSec
          );
          await this.engine.setCustomDeck(deck);

          // 自动勾选并激活 custom 风味
          const curFlavors = this.engine.getState().active_flavors || [];
          if (!curFlavors.includes('custom')) {
            curFlavors.push('custom');
            await this.engine.setActiveFlavors(curFlavors);
          }

          if (timerId) clearInterval(timerId);
          timerId = null;

          if (statusDiv) {
            statusDiv.textContent = `🎉 12 算子甲板已成功生成入库！(总耗时 ${elapsedSec}s)`;
            statusDiv.style.color = '#34d399';
          }
          this.showToast(`🎉 专属 12 算子甲板已生成并成功装载入库！(耗时 ${elapsedSec}s)`);
          this.render();
        } catch (err) {
          if (timerId) clearInterval(timerId);
          timerId = null;

          if (statusDiv) {
            statusDiv.textContent = `❌ 生成中断 (${elapsedSec}s): ${err.message || err}`;
            statusDiv.style.color = '#f87171';
          }
          this.showToast(`❌ 自动生成失败: ${err.message || '请检查API连接'}`);
        } finally {
          if (timerId) clearInterval(timerId);
          btnGenDeck.disabled = false;
          btnGenDeck.style.opacity = '1';
        }
      };
    }

    // 3. 导出全量配置与卡组至本地 .json 文件 (零配额安全)
    const btnExportDeck = this.modalEl.querySelector('#tse-btn-export-deck');
    if (btnExportDeck) {
      btnExportDeck.onclick = () => {
        const state = this.engine.getState();
        const exportData = {
          version: '1.6.0',
          type: 'tse_full_preset',
          exported_at: new Date().toISOString(),
          settings: state.settings ? { ...state.settings } : {},
          active_flavors: state.active_flavors || ['sweet', 'spicy'],
          custom_operators: state.custom_operators || {},
          custom_deck: state.custom_deck || []
        };
        const doc = (typeof document !== 'undefined') ? document : (this.engine.ctx.document || null);
        if (doc && typeof Blob !== 'undefined' && typeof URL !== 'undefined') {
          const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = doc.createElement('a');
          a.href = url;
          a.download = `tse_full_preset_${Date.now()}.json`;
          doc.body.appendChild(a);
          a.click();
          doc.body.removeChild(a);
          URL.revokeObjectURL(url);
          this.showToast('📥 全量配置文件已下载至本地！');
        }
      };
    }

    // 4. 导入本地全量配置或卡组 .json 文件
    const btnImportTrigger = this.modalEl.querySelector('#tse-btn-import-deck-trigger');
    const fileInput = this.modalEl.querySelector('#tse-file-import-input');
    if (btnImportTrigger && fileInput) {
      btnImportTrigger.onclick = () => {
        fileInput.value = '';
        fileInput.click();
      };
      fileInput.onchange = (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = async (ev) => {
          try {
            const parsed = JSON.parse(ev.target.result);
            if (parsed && typeof parsed === 'object') {
              let hasSettings = false;
              if (parsed.settings && typeof parsed.settings === 'object') {
                const curState = this.engine.getState();
                curState.settings = { ...curState.settings, ...parsed.settings };
                this.engine.saveState(curState);
                if (typeof this.engine.ensurePromptsInjected === 'function') {
                  this.engine.ensurePromptsInjected();
                }
                hasSettings = true;
              }
              if (Array.isArray(parsed.custom_deck)) {
                await this.engine.setCustomDeck(parsed.custom_deck);
              }
              if (Array.isArray(parsed.active_flavors)) {
                await this.engine.setActiveFlavors(parsed.active_flavors);
              }
              if (parsed.custom_operators && typeof parsed.custom_operators === 'object') {
                const curState = this.engine.getState();
                curState.custom_operators = { ...curState.custom_operators, ...parsed.custom_operators };
                this.engine.saveState(curState);
              }
              this.showToast(hasSettings ? '📤 全量配置与卡组已成功导入并即时生效！' : '📤 本地卡组配置已成功导入！');
              this.render();
            }
          } catch (err) {
            this.showToast('❌ JSON 解析失败，文件格式有误！');
          }
        };
        reader.readAsText(file, 'utf-8');
      };
    }

    // 套路下拉切换
    const opSelector = this.modalEl.querySelector('#tse-op-selector');
    if (opSelector) {
      opSelector.onchange = (e) => {
        this.selectedOpId = e.target.value;
        this.render();
      };
    }

    // 保存套路意图
    const btnSaveOp = this.modalEl.querySelector('#tse-btn-save-op');
    if (btnSaveOp) {
      btnSaveOp.onclick = async () => {
        const textarea = this.modalEl.querySelector('#tse-op-intent-text');
        if (textarea) {
          const newIntent = textarea.value.trim();
          await this.engine.saveOperatorIntent(this.selectedOpId, newIntent);
          this.showToast(`✔ 套路 [${this.selectedOpId}] 意图已保存！`);
          this.render();
        }
      };
    }

    // 恢复默认套路意图
    const btnResetOp = this.modalEl.querySelector('#tse-btn-reset-op');
    if (btnResetOp) {
      btnResetOp.onclick = async () => {
        await this.engine.resetOperatorIntent(this.selectedOpId);
        this.showToast(`✔ 已恢复 [${this.selectedOpId}] 原版意图！`);
        this.render();
      };
    }

    // 子标签切换 (D1 vs D0)
    const subTabBtns = this.modalEl.querySelectorAll('.tse-subtab-btn');
    subTabBtns.forEach(btn => {
      btn.onclick = () => {
        this.promptSubTab = btn.getAttribute('data-subtab');
        this.render();
      };
    });

    // 保存 D1 伴生协议
    const btnSaveD1 = this.modalEl.querySelector('#tse-btn-save-d1');
    if (btnSaveD1) {
      btnSaveD1.onclick = async () => {
        const textarea = this.modalEl.querySelector('#tse-input-d1-protocol');
        const depthInput = this.modalEl.querySelector('#tse-input-d1-depth');
        const depth = parseInt(depthInput ? depthInput.value : '1', 10);
        const text = textarea ? textarea.value.trim() : '';
        await this.engine.saveD1Protocol(text, isNaN(depth) ? 1 : depth);
        this.showToast('✔ D1 伴生协议已保存并即时热更新！');
        this.render();
      };
    }

    // 重置 D1 伴生协议
    const btnResetD1 = this.modalEl.querySelector('#tse-btn-reset-d1');
    if (btnResetD1) {
      btnResetD1.onclick = async () => {
        await this.engine.resetD1Protocol();
        this.showToast('✔ 已恢复官方原版伴生协议！');
        this.render();
      };
    }

    // 保存发糖节奏 (Tab 2 快捷设置)
    const btnSaveStatusRhythm = this.modalEl.querySelector('#tse-btn-save-status-rhythm');
    if (btnSaveStatusRhythm) {
      btnSaveStatusRhythm.onclick = async () => {
        const durationInput = this.modalEl.querySelector('#tse-input-status-duration');
        const cooldownInput = this.modalEl.querySelector('#tse-input-status-cooldown');
        const duration = parseInt(durationInput ? durationInput.value : '2', 10);
        const cooldown = parseInt(cooldownInput ? cooldownInput.value : '1', 10);
        await this.engine.saveRhythmSettings(
          isNaN(duration) ? 2 : duration,
          isNaN(cooldown) ? 1 : cooldown
        );
        this.showToast('✔ 发糖持续时间与冷却 CD 已更新！');
        this.render();
      };
    }

    // 保存 D0 发糖骨架模板与深度、持续、冷却配置
    const btnSaveD0 = this.modalEl.querySelector('#tse-btn-save-d0');
    if (btnSaveD0) {
      btnSaveD0.onclick = async () => {
        const textarea = this.modalEl.querySelector('#tse-input-d0-template');
        const depthInput = this.modalEl.querySelector('#tse-input-d0-depth');
        const durationInput = this.modalEl.querySelector('#tse-input-d0-duration');
        const cooldownInput = this.modalEl.querySelector('#tse-input-d0-cooldown');

        const depth = parseInt(depthInput ? depthInput.value : '0', 10);
        const duration = parseInt(durationInput ? durationInput.value : '2', 10);
        const cooldown = parseInt(cooldownInput ? cooldownInput.value : '1', 10);
        const text = textarea ? textarea.value.trim() : '';

        const patch = { d0_template: text };
        if (!isNaN(depth)) patch.d0_depth = depth;
        if (!isNaN(duration) && duration >= 1) patch.sweet_duration = duration;
        if (!isNaN(cooldown) && cooldown >= 0) patch.sweet_cooldown = cooldown;

        await this.engine.updateSettings(patch);
        this.showToast('✔ D0 发糖骨架模板与节奏配置已保存并即时热更新！');
        this.render();
      };
    }

    // 重置 D0 发糖骨架模板
    const btnResetD0 = this.modalEl.querySelector('#tse-btn-reset-d0');
    if (btnResetD0) {
      btnResetD0.onclick = async () => {
        await this.engine.resetD0Template();
        this.showToast('✔ 已恢复官方原版发糖骨架模板！');
        this.render();
      };
    }
  }
}

  // =========================================
  // Module: engine_core.js
  // =========================================

/**
 * TSE (Tension & Sweetness Engine) 动态发糖卡牌引擎 - 核心调度中枢
 * 模块：engine_core.js
 */

class TseEngine {
  constructor(hostContext) {
    this.ctx = hostContext || {};
    this.isProcessing = false;
    this.lastHandledFloor = -1;
    this.disposers = [];
    this.memoryState = null;
    this.boundChatId = null;
    this.lastAiCompletedAt = 0;
    this.hud = new TseHUD(this);
  }

  /**
   * 安全获取宿主或酒馆助手 API
   */
  getApi(name) {
    if (this.ctx[name]) return this.ctx[name];
    if (typeof global !== 'undefined' && typeof global[name] === 'function') return global[name];
    if (typeof window !== 'undefined' && typeof window[name] === 'function') return window[name];
    if (typeof window !== 'undefined' && window.TavernHelper && typeof window.TavernHelper[name] === 'function') {
      return window.TavernHelper[name];
    }
    return null;
  }

  /**
   * 获取当前会话唯一标识（用于严格隔离跨会话、并在同会话内免疫外部冲刷）
   */
  getCurrentSessionId() {
    const getChatId = this.getApi('getCurrentChatId');
    if (typeof getChatId === 'function') {
      try {
        const id = getChatId();
        if (id) return String(id);
      } catch (e) {}
    }
    if (typeof global !== 'undefined' && typeof global.getCurrentChatId === 'function') {
      try {
        const id = global.getCurrentChatId();
        if (id) return String(id);
      } catch (e) {}
    }
    if (typeof window !== 'undefined') {
      if (typeof window.getCurrentChatId === 'function') {
        try {
          const id = window.getCurrentChatId();
          if (id) return String(id);
        } catch (e) {}
      }
      if (window.SillyTavern && typeof window.SillyTavern.getCurrentChatId === 'function') {
        try {
          const id = window.SillyTavern.getCurrentChatId();
          if (id) return String(id);
        } catch (e) {}
      }
    }
    return null;
  }

  /**
   * 判断前端是否正处于消息编辑状态（防止编辑旧楼层触发误杀）
   */
  isEditingMode() {
    try {
      if (typeof window !== 'undefined') {
        if (typeof window.this_edit_mes_id === 'number' && window.this_edit_mes_id >= 0) {
          return true;
        }
      }
      const checkDoc = (d) => {
        if (!d || typeof d.querySelector !== 'function') return false;
        try {
          if (d.querySelector('#curEditTextarea')) return true;
          const doneBtn = d.querySelector('.mes_edit_done');
          if (doneBtn && (doneBtn.offsetParent !== null || doneBtn.style.display !== 'none')) return true;
        } catch (e) {}
        return false;
      };

      const doc = (typeof document !== 'undefined') ? document : (this.ctx.document || null);
      if (checkDoc(doc)) return true;

      if (typeof window !== 'undefined' && window.parent && window.parent.document) {
        if (checkDoc(window.parent.document)) return true;
      }
    } catch (e) {}
    return false;
  }

  /**
   * 安全获取当前会话真实的物理全楼层末尾索引
   */
  getActualChatFloor() {
    try {
      const getMessages = this.getApi('getChatMessages');
      if (typeof getMessages === 'function') {
        const all = getMessages('0-', { role: 'all', hide_state: 'all' });
        if (Array.isArray(all) && all.length > 0) {
          return all.length - 1;
        }
      }
      const getLastId = this.getApi('getLastMessageId');
      if (typeof getLastId === 'function') {
        const id = getLastId();
        if (typeof id === 'number' && id >= 0) return id;
      }
    } catch (e) {}
    return -1;
  }

  /**
   * 坚固的变量持久化通道（优先 insertOrAssign 增量合并，防止被 replace 抹除）
   */
  saveState(state) {
    if (!state) return;
    this.memoryState = state;
    const updateVars = this.getApi('updateVariablesWith');
    if (typeof updateVars === 'function') {
      try {
        updateVars(v => {
          v.tse_engine = state;
          return v;
        }, { type: 'chat' });
        return;
      } catch (e) {}
    }
    const insertOrAssign = this.getApi('insertOrAssignVariables');
    if (typeof insertOrAssign === 'function') {
      try {
        insertOrAssign({ tse_engine: state }, { type: 'chat' });
        return;
      } catch (e) {}
    }
  }

  /**
   * 获取当前引擎状态快照
   */
  getState() {
    return this.memoryState || this.createDefaultState();
  }

  /**
   * 创建初始状态
   */
  createDefaultState() {
    const initialCoord = [0.0, 0.0];
    const initialQuadrant = 'Q1';
    const initialFlavors = ['sweet', 'spicy'];
    return {
      coord: initialCoord,
      confirmed_quadrant: initialQuadrant,
      active_flavors: initialFlavors,
      custom_deck: [],
      pacing_fatigue: false,
      recent_user_lengths: [],
      hand: buildHand(initialCoord, initialQuadrant, {}, initialFlavors, [], false, []),
      graveyard: [],
      recently_played: [],
      active_buff: null,
      cool_off_turns: 0,
      last_target: 'none',
      last_note: '',
      total_hits: 0,
      custom_operators: {}, // 用户在线自定义修改的套路意图覆盖
      committed_floor: -1, // 上一次已正式定稿结算的 AI 楼层索引
      draft_meta: null,     // 当前候选草稿（未定稿，待接话锁定）
      settings: {
        d0_depth: 0,
        d1_depth: 1,
        d0_template: '',
        d1_protocol: '',
        sweet_duration: DEFAULT_TTL,
        sweet_cooldown: DEFAULT_COOLDOWN,
        generator_timeout: 240
      },
      dmp: {
        affinity_targets: {},
        recent_targets: [],
        current_focus: null,
        is_remote_echo: false
      }
    };
  }

  /**
   * 确保 chat 作用域变量初始化
   */
  ensureInitialized() {
    const getVars = this.getApi('getVariables');
    if (!getVars) return;

    const currentChatId = this.getCurrentSessionId();
    const isSameSession = !!(this.boundChatId && currentChatId && this.boundChatId === currentChatId);

    const vars = getVars({ type: 'chat' }) || {};
    if (vars.tse_engine) {
      // 作用域内已有正常持久化变量，装载至内存并绑定当前会话
      this.memoryState = vars.tse_engine;
      if (currentChatId) {
        this.boundChatId = currentChatId;
      }
    } else if (isSameSession && this.memoryState) {
      // 🛡️ 同会话变量丢失保护：外部脚本（如太玄状态栏）调用 replaceVariables 抹杀了变量，但当前会话仍未切换
      console.warn('[TSE Engine] 🛡️ 检测到同会话内变量被外部脚本冲刷，触发内存状态自愈保护，立即重新写回宿主！');
      this.saveState(this.memoryState);
    } else {
      // 确实是首次加载或新建会话，创建初始白板
      const state = this.createDefaultState();
      this.memoryState = state;
      if (currentChatId) {
        this.boundChatId = currentChatId;
      }
      this.saveState(state);
    }

    if (this.memoryState) {
      // 兼容补全 settings 与 custom_operators
      if (!this.memoryState.settings) {
        this.memoryState.settings = {
          d0_depth: 0,
          d1_depth: 1,
          d0_template: '',
          d1_protocol: '',
          sweet_duration: DEFAULT_TTL,
          sweet_cooldown: DEFAULT_COOLDOWN
        };
      }
      if (this.memoryState.settings.d0_template === undefined) {
        this.memoryState.settings.d0_template = '';
      }
      if (this.memoryState.settings.d1_protocol === undefined) {
        this.memoryState.settings.d1_protocol = '';
      }
      if (this.memoryState.settings.sweet_duration === undefined) {
        this.memoryState.settings.sweet_duration = DEFAULT_TTL;
      }
      if (this.memoryState.settings.sweet_cooldown === undefined) {
        this.memoryState.settings.sweet_cooldown = DEFAULT_COOLDOWN;
      }
      if (!this.memoryState.custom_operators) {
        this.memoryState.custom_operators = {};
      }
      if (!this.memoryState.active_flavors) {
        this.memoryState.active_flavors = ['sweet', 'spicy'];
      }
      if (!this.memoryState.custom_deck) {
        this.memoryState.custom_deck = [];
      }
      if (this.memoryState.pacing_fatigue === undefined) {
        this.memoryState.pacing_fatigue = false;
      }
      if (!this.memoryState.recent_user_lengths) {
        this.memoryState.recent_user_lengths = [];
      }
      if (!this.memoryState.dmp) {
        this.memoryState.dmp = {
          affinity_targets: {},
          recent_targets: [],
          current_focus: null,
          is_remote_echo: false
        };
      } else {
        if (!Array.isArray(this.memoryState.dmp.recent_targets)) {
          this.memoryState.dmp.recent_targets = [];
        }
        if (this.memoryState.dmp.current_focus === undefined) {
          this.memoryState.dmp.current_focus = null;
        }
        if (this.memoryState.dmp.is_remote_echo === undefined) {
          this.memoryState.dmp.is_remote_echo = false;
        }
        /* 2026-09-13 停记迁徙: 自由文本原型直方图无消费者且开放词表无聚合信号, 遗留数据清除 */
        if (this.memoryState.dmp.affinity_archetypes !== undefined) {
          delete this.memoryState.dmp.affinity_archetypes;
        }
      }
      if (typeof this.memoryState.committed_floor !== 'number') {
        this.memoryState.committed_floor = -1;
      }
      if (this.memoryState.draft_meta === undefined) {
        this.memoryState.draft_meta = null;
      }

      // 楼层一致性审计：防止读取到被旧版本跨会话残留污染的超前楼层/卡牌数据
      // ⚠️ 处于消息编辑模式时严禁执行回退注销，杜绝误杀生效中的卡牌！
      if (!this.isEditingMode()) {
        const currentFloor = this.getActualChatFloor();
        if (typeof currentFloor === 'number' && currentFloor >= 0) {
          if (this.memoryState.committed_floor > currentFloor) {
            console.warn(`[TSE Engine] ⚠️ 检测到定稿基线 (${this.memoryState.committed_floor}) 超前于当前楼层 (${currentFloor})，执行基线自愈对齐`);
            this.memoryState.committed_floor = Math.max(-1, currentFloor - 2);
            this.memoryState.draft_meta = null;
          }
          if (this.memoryState.active_buff && typeof this.memoryState.active_buff.start_floor === 'number' && this.memoryState.active_buff.start_floor > currentFloor) {
            console.warn(`[TSE Engine] ⚠️ 检测到活跃卡牌生效楼层 (${this.memoryState.active_buff.start_floor}) 超前于当前楼层 (${currentFloor})，注销幽灵卡牌`);
            this.memoryState.active_buff = null;
            const uninject = this.getApi('uninjectPrompts');
            if (uninject) uninject([INJECT_ID]);
          }
        }
      }
    }
  }

  /**
   * 象限判定辅助方法
   */
  detectQuadrant(x, y, currentQuadrant) {
    return detectQuadrant(x, y, currentQuadrant);
  }

  /**
   * 卡组构建辅助方法 (支持 graveyard 大牌库消耗轮替)
   */
  buildHand(coord, quadrant, customOperators, graveyard) {
    const s = this.getState();
    return buildHand(
      coord,
      quadrant,
      customOperators || s.custom_operators,
      s.active_flavors,
      s.custom_deck,
      s.pacing_fatigue,
      graveyard || s.graveyard || []
    );
  }

  /**
   * 持久化保存单个套路算子的自定义修改
   */
  async saveOperatorIntent(opId, newIntent) {
    const updateVars = this.getApi('updateVariablesWith');
    const state = this.getState();
    if (!state.custom_operators) state.custom_operators = {};
    state.custom_operators[opId] = newIntent;
    this.memoryState = state;

    if (updateVars) {
      updateVars(v => {
        v.tse_engine = state;
        return v;
      }, { type: 'chat' });
    }

    // 若当前正在打出的卡牌正好被修改，即时刷新注入
    if (state.active_buff && state.active_buff.id === opId) {
      state.active_buff.intent = newIntent;
      injectD0Prompt(this.getApi.bind(this), state.active_buff, state.dmp, state.settings, state);
    }
  }

  /**
   * 恢复单个套路算子的默认意图
   */
  async resetOperatorIntent(opId) {
    const updateVars = this.getApi('updateVariablesWith');
    const state = this.getState();
    if (state.custom_operators && state.custom_operators[opId]) {
      delete state.custom_operators[opId];
    }
    this.memoryState = state;

    if (updateVars) {
      updateVars(v => {
        v.tse_engine = state;
        return v;
      }, { type: 'chat' });
    }

    if (state.active_buff && state.active_buff.id === opId) {
      const orig = OPERATORS_DB.find(o => o.id === opId);
      if (orig) {
        state.active_buff.intent = orig.intent;
        injectD0Prompt(this.getApi.bind(this), state.active_buff, state.dmp, state.settings, state);
      }
    }
  }

  /**
   * 更新深度与伴生协议配置并热更新注入
   */
  async updateSettings(newSettings = {}) {
    const updateVars = this.getApi('updateVariablesWith');
    const state = this.getState();
    state.settings = { ...state.settings, ...newSettings };
    this.memoryState = state;

    if (updateVars) {
      updateVars(v => {
        v.tse_engine = state;
        return v;
      }, { type: 'chat' });
    }

    // 重新挂载伴生协议与活动卡牌
    injectCompanionProtocol(this.getApi.bind(this), state.settings);
    if (state.active_buff) {
      injectD0Prompt(this.getApi.bind(this), state.active_buff, state.dmp, state.settings, state);
    }
  }

  /**
   * 保存伴生心流标签协议 (D1)
   */
  async saveD1Protocol(protocol, depth) {
    const patch = { d1_protocol: protocol };
    if (typeof depth === 'number' && !isNaN(depth)) {
      patch.d1_depth = depth;
    }
    await this.updateSettings(patch);
  }

  /**
   * 恢复默认伴生心流标签协议 (D1)
   */
  async resetD1Protocol() {
    await this.updateSettings({ d1_protocol: '' });
  }

  /**
   * 保存发糖导向卡牌主模板 (D0)
   */
  async saveD0Template(template, depth) {
    const patch = { d0_template: template };
    if (typeof depth === 'number' && !isNaN(depth)) {
      patch.d0_depth = depth;
    }
    await this.updateSettings(patch);
  }

  /**
   * 恢复默认发糖导向卡牌主模板 (D0)
   */
  async resetD0Template() {
    await this.updateSettings({ d0_template: '' });
  }

  /**
   * 保存发糖节奏参数 (持续时间与冷却CD)
   */
  async saveRhythmSettings(duration, cooldown) {
    const patch = {};
    if (typeof duration === 'number' && !isNaN(duration) && duration >= 1) {
      patch.sweet_duration = Math.floor(duration);
    }
    if (typeof cooldown === 'number' && !isNaN(cooldown) && cooldown >= 0) {
      patch.sweet_cooldown = Math.floor(cooldown);
    }
    await this.updateSettings(patch);
  }

  /**
   * 恢复默认发糖节奏 (持续 2 回合, CD 1 回合)
   */
  async resetRhythmSettings() {
    await this.updateSettings({
      sweet_duration: DEFAULT_TTL,
      sweet_cooldown: DEFAULT_COOLDOWN
    });
  }

  /**
   * 玩家主动一键清空并重置当前对话的发糖状态为初始白板
   */
  async resetCurrentChatState() {
    console.log('[TSE Engine] 🧹 玩家执行【一键清空重置本对话发糖状态】...');
    this.memoryState = null;
    this.lastHandledFloor = -1;
    this.lastMessageSignature = null;

    const defaultState = this.createDefaultState();
    this.memoryState = defaultState;

    const updateVars = this.getApi('updateVariablesWith');
    if (updateVars) {
      updateVars(v => {
        v.tse_engine = defaultState;
        return v;
      }, { type: 'chat' });
    }

    // 彻底卸载 D0 发糖提示词
    const uninject = this.getApi('uninjectPrompts');
    if (uninject) {
      uninject([INJECT_ID]);
    }

    // 重新挂载纯净 D1 伴生协议
    this.ensurePromptsInjected();

    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
    console.log('[TSE Engine] ✔ 当前对话发糖状态已彻底清空并恢复为初始白板！');
  }

  /**
   * 玩家主动一键清空 DMP 好感度总榜与近期 10 回合焦点队列
   */
  async clearDmpData() {
    console.log('[TSE Engine] 🗑️ 玩家执行【一键清空重置角色羁绊好感度】...');
    const state = this.getState();
    state.dmp = {
      affinity_targets: {},
      recent_targets: [],
      current_focus: null,
      is_remote_echo: false
    };
    state.last_target = null;
    this.memoryState = state;

    // 🛡️ 强制更新持久化变量表，杜绝深层合并保留旧键名导致的下一轮“自愈”
    const updateVars = this.getApi('updateVariablesWith');
    if (typeof updateVars === 'function') {
      try {
        updateVars(v => {
          if (v.tse_engine) {
            v.tse_engine.dmp = {
              affinity_targets: {},
              recent_targets: [],
              current_focus: null,
              is_remote_echo: false
            };
            v.tse_engine.last_target = null;
          }
          return v;
        }, { type: 'chat' });
      } catch (e) {
        console.warn('[TSE Engine] updateVariablesWith 清空 DMP 异常:', e);
      }
    }

    this.saveState(state);

    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
    console.log('[TSE Engine] ✔ 已清空 DMP 好感度记录与近期滑动窗口焦点！');
  }

  /**
   * 确保伴生协议与发糖活动卡牌在当前聊天中就位注入
   */
  ensurePromptsInjected() {
    this.ensureInitialized();
    const state = this.getState();
    // 1. 常驻挂载 D1 伴生协议
    injectCompanionProtocol(this.getApi.bind(this), state.settings);
    // 2. 若存在活跃发糖卡牌，补全挂载 D0 提示词；若无活跃卡牌，必须彻底卸载 D0 提示词！
    if (state.active_buff) {
      injectD0Prompt(this.getApi.bind(this), state.active_buff, state.dmp, state.settings, state);
    } else {
      const uninject = this.getApi('uninjectPrompts');
      if (uninject) {
        uninject([INJECT_ID]);
      }
    }
  }

  /**
   * 对话切换或新建时的全量自愈重对齐
   */
  onChatSwitched(incomingChatId, isNewChat = false) {
    const newChatId = incomingChatId || this.getCurrentSessionId();
    const isSameSession = !isNewChat && !!(this.boundChatId && newChatId && this.boundChatId === newChatId && this.memoryState);

    if (!isSameSession) {
      console.log('[TSE Engine] 🔄 检测到真实对话切换/新开，自动对齐作用域并补全注入协议...');
      this.lastHandledFloor = -1;
      this.lastMessageSignature = null;
      this.memoryState = null; // 彻底斩断跨对话内存状态污染！
      this.boundChatId = newChatId || null;

      // 切换会话时强制卸载上一会话的 D0 卡牌提示词
      const uninject = this.getApi('uninjectPrompts');
      if (uninject) {
        uninject([INJECT_ID]);
      }
    } else {
      console.log(`[TSE Engine] ℹ️ 会话未发生实际变更 (${newChatId})，维持内存状态并自愈补全提示词`);
    }

    this.ensureInitialized();
    this.ensurePromptsInjected();
    if (this.hud) {
      this.hud.mountWandMenuEntry();
      if (this.hud.isOpen) {
        this.hud.render();
      }
    }
  }

  /**
   * 初始化引擎
   */
  init() {
    this.destroy();
    console.log('[TSE Engine] 动态发糖卡牌引擎正在启动 (含悬浮中枢与人类可读追踪)...');

    this.ensureInitialized();

    // 1. 常驻挂载 D1 伴生协议与活动卡牌
    this.ensurePromptsInjected();

    // 2. 挂载隐形清洗守卫 (纯全局正则，单次防重)
    try {
      injectCleanerGuard(this.getApi.bind(this), this.getState());
    } catch (e) {}

    // 3. 挂载右下角轻奢悬浮球
    try {
      this.hud.mount();
    } catch (err) {
      console.warn('[TSE Engine] HUD 挂载失败:', err);
    }

    // 3. 事件监听与驱动
    const eventOn = this.getApi('eventOn');
    const tavern_events = (typeof global !== 'undefined' && global.tavern_events) || this.ctx.tavern_events || {};

    if (eventOn) {
      // 3.1 监听玩家发送消息 (定稿上一轮，为下一轮生成准备卡牌)
      const sentEvent = tavern_events.MESSAGE_SENT || 'message_sent';
      const subSent = eventOn(sentEvent, async (messageId) => {
        await this.onTurnStep(messageId);
      });
      this.disposers.push(subSent.stop);

      // 3.2 监听 AI 回复到达 (捕获草稿，前台隐形清洗)
      const recvEvent = tavern_events.MESSAGE_RECEIVED || 'message_received';
      const subRecv = eventOn(recvEvent, async (messageId, type) => {
        if (type === 'quiet' || type === 'extension') return;
        await this.onTurnStep(messageId);
      });
      this.disposers.push(subRecv.stop);

      // 3.3 监听 Swipe 划动切换
      const swipeEvent = tavern_events.MESSAGE_SWIPED || 'message_swiped';
      const subSwipe = eventOn(swipeEvent, async (messageId) => {
        await this.onSwipeStep(messageId);
      });
      this.disposers.push(subSwipe.stop);

      // 3.4 监听对话切换与新建 (新开对话 / 切换历史会话)
      const chatChangedEvent = tavern_events.CHAT_CHANGED || 'chat_id_changed';
      const subChat = eventOn(chatChangedEvent, (newChatId) => {
        this.onChatSwitched(newChatId, false);
      });
      this.disposers.push(subChat.stop);

      const chatCreatedEvent = tavern_events.CHAT_CREATED || 'chat_created';
      const subCreate = eventOn(chatCreatedEvent, (newChatId) => {
        this.onChatSwitched(newChatId, true);
      });
      this.disposers.push(subCreate.stop);

      // 3.5 监听生成前流水线 (在 prompt 组合与发送给模型前自愈重注与挂载)
      const genEvent = tavern_events.GENERATION_AFTER_COMMANDS || 'GENERATION_AFTER_COMMANDS';
      const subGen = eventOn(genEvent, () => {
        this.ensurePromptsInjected();
        if (this.hud) this.hud.mountWandMenuEntry();
      });
      this.disposers.push(subGen.stop);

      const combineEvent = tavern_events.GENERATE_BEFORE_COMBINE_PROMPTS || 'generate_before_combine_prompts';
      const subCombine = eventOn(combineEvent, () => {
        this.ensurePromptsInjected();
        if (this.hud) this.hud.mountWandMenuEntry();
      });
      this.disposers.push(subCombine.stop);

      // 3.6 注册酒馆助手（Tavern Helper）脚本按钮与事件驱动
      try {
        const LAUNCHER_BUTTON_NAME = '🍬 TSE控制台';
        const getButtonEvent = this.getApi('getButtonEvent');
        const updateScriptButtonsWith = this.getApi('updateScriptButtonsWith');
        const appendInexistentScriptButtons = this.getApi('appendInexistentScriptButtons');

        if (typeof updateScriptButtonsWith === 'function') {
          updateScriptButtonsWith((buttons) => {
            const next = (Array.isArray(buttons) ? buttons : []);
            if (!next.some(b => b?.name === LAUNCHER_BUTTON_NAME)) {
              // 默认关闭 (visible: false)，避免挤占聊天窗口空间；用户可通过魔术棒扩展菜单或悬浮球随时呼出
              next.push({ name: LAUNCHER_BUTTON_NAME, visible: false });
            }
            return next;
          });
        } else if (typeof appendInexistentScriptButtons === 'function') {
          appendInexistentScriptButtons([{ name: LAUNCHER_BUTTON_NAME, visible: false }]);
        }

        if (typeof getButtonEvent === 'function' && eventOn) {
          const eventName = getButtonEvent(LAUNCHER_BUTTON_NAME);
          if (eventName) {
            const subBtn = eventOn(eventName, () => {
              if (this.hud) {
                this.hud.toggle();
              }
            });
            if (subBtn && typeof subBtn.stop === 'function') {
              this.disposers.push(subBtn.stop);
            }
          }
        }
      } catch (e) {
        console.warn('[TSE Engine] 注册酒馆助手脚本按钮失败:', e);
      }

      // 3.7 注册 /tse 斜杠命令支持 (可选无干扰呼出)
      const SlashCommandParser = this.getApi('SlashCommandParser') || (typeof global !== 'undefined' && global.SlashCommandParser);
      const SlashCommand = this.getApi('SlashCommand') || (typeof global !== 'undefined' && global.SlashCommand);
      if (SlashCommandParser && SlashCommand) {
        try {
          SlashCommandParser.addCommandObject(SlashCommand.fromProps({
            name: 'tse',
            callback: () => {
              if (this.hud) {
                this.hud.toggle();
              }
              return '';
            },
            helpString: '打开或关闭 TSE 动态发糖卡牌引擎控制台'
          }));
        } catch (e) {}
      }
    }
  }

  /**
   * 从最新正文提取伴生评估数据 <tse_meta>
   */
  extractMeta(messageText) {
    if (!messageText || typeof messageText !== 'string') return null;

    // 0. 关键物理防护：彻底切除思维链 / 推理块 (Chain of Thought)，杜绝内部思考草稿泄露
    let sanitizedText = messageText
      .replace(/<think\b[\s\S]*?<\/think>/gi, '')
      .replace(/<thought\b[\s\S]*?<\/thought>/gi, '')
      .replace(/<thinking\b[\s\S]*?<\/thinking>/gi, '')
      .replace(/<details\b[^>]*\bclass=["']?(?:thought|thinking)["']?[^>]*>[\s\S]*?<\/details>/gi, '')
      .replace(/```(?:thought|thinking)[\s\S]*?```/gi, '');

    // 防御截断未闭合的思维链
    sanitizedText = sanitizedText.replace(/<think\b[\s\S]*$/gi, '');

    let attrText = '';
    let bodyText = '';

    // 1. 倒序捕获：在剥离思维链后的全量文本中，精确提取【最后一个出现的完整闭合伴生标签】
    // 无论后面跟了多少万字的角色 Memory 或 status_bar，都不受切片限制影响，稳健锚定真实收尾标签
    const allMatches = [...sanitizedText.matchAll(/<tse_meta(?:\s+([^>]*?))?>([\s\S]*?)<\/tse_meta>/gi)];
    if (allMatches.length > 0) {
      const lastMatch = allMatches[allMatches.length - 1];
      attrText = lastMatch[1] || '';
      bodyText = lastMatch[2] || '';
    } else {
      // 容错自闭合标签，同样取最后一个
      const allSelfMatches = [...sanitizedText.matchAll(/<tse_meta\s+([^>]*?)\/?>/gi)];
      if (allSelfMatches.length > 0) {
        const lastSelf = allSelfMatches[allSelfMatches.length - 1];
        attrText = lastSelf[1] || '';
      }
    }

    const combined = `${attrText} ${bodyText}`.trim();
    if (!combined) return null;

    // 模式 A: 纯 JSON 尝试
    const pureJsonTarget = bodyText.trim().startsWith('{') ? bodyText.trim() : combined;
    if (pureJsonTarget.startsWith('{') && pureJsonTarget.endsWith('}')) {
      try {
        const sanitized = pureJsonTarget
          .replace(/,\s*([}\]])/g, '$1')
          .replace(/'/g, '"')
          .replace(/([{,]\s*)([a-zA-Z0-9_]+)\s*:/g, '$1"$2":');
        const parsed = JSON.parse(sanitized);
        if (parsed && typeof parsed === 'object') {
          if (parsed.sweet) parsed.sweet = String(parsed.sweet).trim();
          if (parsed.player_mind) {
            const rawMind = String(parsed.player_mind).trim();
            parsed.note = rawMind.length > 80 ? rawMind.slice(0, 80).trim() : rawMind;
          }
          return parsed;
        }
      } catch (e) {}
    }

    // 模式 B: 正则宽容降级
    try {
      const result = {};
      const matchX = combined.match(/x["']?\s*[:=]\s*["']?(-?[\d.]+)["']?/i);
      if (matchX) result.x = parseFloat(matchX[1]);

      const matchY = combined.match(/y["']?\s*[:=]\s*["']?(-?[\d.]+)["']?/i);
      if (matchY) result.y = parseFloat(matchY[1]);

      const matchTarget = combined.match(/target["']?\s*[:=]\s*["']?([^"',}\s>]+(?:\[[^\]]*?\])?)["']?/i);
      if (matchTarget) result.target = matchTarget[1].trim();

      const matchHit = combined.match(/hit["']?\s*[:=]\s*["']?(true|false)["']?/i);
      if (matchHit) result.hit = matchHit[1].toLowerCase() === 'true';

      const matchSweet = combined.match(/sweet["']?\s*[:=]\s*["']?([^"',}\s>]+)["']?/i);
      if (matchSweet) result.sweet = matchSweet[1].trim();

      if (bodyText && bodyText.trim()) {
        let cleanNote = bodyText.replace(/^[^{]*\{[\s\S]*?\}/, '').trim();
        // 优先提取 <player_mind> 标签内部的白描文本
        const mindMatch = cleanNote.match(/<player_mind>([\s\S]*?)<\/player_mind>/i);
        if (mindMatch) {
          cleanNote = mindMatch[1].trim();
        } else {
          // 若标签漏闭合或不完整，安全剥离残留的标签包裹
          cleanNote = cleanNote.replace(/<\/?player_mind>/gi, '').trim();
        }
        if (cleanNote) {
          result.note = cleanNote.length > 80 ? cleanNote.slice(0, 80).trim() : cleanNote;
        }
      }

      if (typeof result.x === 'number' && typeof result.y === 'number') {
        return result;
      }
    } catch (err) {
      console.warn('[TSE Engine] 容错正则提取异常:', err);
    }

    return null;
  }

  /**
   * 每回合核心驱动（两阶段提交架构）
   * 阶段 1：AI 消息到达时（-1 楼）捕获草稿与物理清洗，绝不扣减 TTL / 卡牌耐受度
   * 阶段 2：玩家接话发送消息时（-2 楼定稿）正式定稿结算并打出下一轮卡牌
   */
  async onTurnStep(messageId) {
    if (this.isProcessing) return;
    this.isProcessing = true;

    try {
      const getMessages = this.getApi('getChatMessages');
      const getVars = this.getApi('getVariables');
      const getLastId = this.getApi('getLastMessageId');

      if (!getMessages || !getVars) return;

      const recent = getMessages('-1', { role: 'all', hide_state: 'all' });
      if (!recent || recent.length === 0) return;
      const lastMsg = recent[0];
      const text = lastMsg.message || lastMsg.mes || lastMsg.text || '';
      const role = lastMsg.is_user ? 'user' : (lastMsg.role || (lastMsg.is_system ? 'system' : 'assistant'));

      const actualFloor = this.getActualChatFloor();
      const currentFloor = actualFloor >= 0 ? actualFloor : (typeof getLastId === 'function' ? getLastId() : messageId);

      // 幂等防重守卫：若楼层、角色与内容哈希完全一致，避免重复执行
      const msgSignature = `${currentFloor}_${role}_${text.length}_${text.slice(-30)}`;
      if (this.lastMessageSignature === msgSignature) {
        return;
      }
      this.lastMessageSignature = msgSignature;

      const currentVars = getVars({ type: 'chat' }) || {};
      let state = currentVars.tse_engine || this.memoryState || this.createDefaultState();
      this.memoryState = state;

      // 楼层回退时光倒流自愈检查 (处于编辑模式时挂起，绝不误杀生效中卡牌)
      if (!this.isEditingMode() && typeof currentFloor === 'number' && currentFloor >= 0) {
        if (currentFloor <= state.committed_floor) {
          console.log(`[TSE Engine] 🔄 检测到楼层回退 (当前: ${currentFloor}, 已定稿基线: ${state.committed_floor})，自愈同步基线！`);
          state.committed_floor = Math.max(-1, currentFloor - 2);
          state.draft_meta = null;
        }
        if (state.active_buff && typeof state.active_buff.start_floor === 'number' && currentFloor < state.active_buff.start_floor) {
          console.log(`[TSE Engine] 🔄 检测到当前楼层 (${currentFloor}) 已回退至卡牌生效楼层 (${state.active_buff.start_floor}) 之前，注销失效卡牌！`);
          state.active_buff = null;
          const uninject = this.getApi('uninjectPrompts');
          if (uninject) uninject([INJECT_ID]);
        }
      }

      if (role === 'assistant') {
        await this.handleAssistantDraft(lastMsg, currentFloor, state);
      } else if (role === 'user') {
        await this.handleUserCommit(lastMsg, currentFloor, state);
      }
    } catch (err) {
      console.error('[TSE Engine] 回合处理异常:', err);
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * 处理 AI 回复（草稿阶段）
   * 物理级脱敏，捕获草稿，绝不扣减卡牌耐受或 TTL，彻底免疫 Swipe / 重Roll 震荡
   */
  async handleAssistantDraft(lastMsg, currentFloor, state) {
    // 连续 assistant 消息检测 (如用户点击 Continue 顺承上一楼)
    const prevFloor = currentFloor - 1;
    if (prevFloor >= 0 && prevFloor > state.committed_floor && state.draft_meta) {
      console.log(`[TSE Engine] ⏩ 检测到连续 AI 楼层 (Continue)，自动定稿前一楼 (第 ${prevFloor + 1} 楼)`);
      this.commitTurn(state, state.draft_meta, prevFloor);
      state.committed_floor = prevFloor;
      state.draft_meta = null;
    }

    // 1. 提取伴生元数据 <tse_meta>，存入候选草稿 draft_meta
    const text = lastMsg.message || lastMsg.mes || lastMsg.text || '';
    const meta = this.extractMeta(text);
    if (meta) {
      state.draft_meta = meta;
      console.log(`[TSE Engine] 📝 捕获到第 ${currentFloor + 1} 楼 AI 候选草稿 (目标:[${meta.target || '无'}]) · 待接话后定稿锁定`);
    }

    // 3. 记录当前 AI 完成输出的物理绝对时间戳
    this.lastAiCompletedAt = Date.now();

    // 4. 草稿阶段：绝不扣减 TTL，绝不扣减卡牌耐受度，绝不漂移坐标！
    this.saveState(state);

    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
  }

  /**
   * 处理用户消息（定稿提交阶段）
   * 用户打字发送即表示对前一轮 AI 输出认可，定稿结算前一楼，推进状态机，并为下一轮 AI 打出新卡
   */
  async handleUserCommit(lastMsg, currentFloor, state) {
    const now = Date.now();
    const reactionDelta = (this.lastAiCompletedAt > 0) ? (now - this.lastAiCompletedAt) : 0;
    const validDelta = Math.min(Math.max(reactionDelta, 0), 180000);

    // 统计玩家本轮输入的有效字数与疲态感知
    const rawInput = lastMsg.message || lastMsg.mes || lastMsg.text || '';
    const cleanText = rawInput.replace(/\s+/g, '');
    const charLen = cleanText.length;
    if (!state.recent_user_lengths) state.recent_user_lengths = [];
    state.recent_user_lengths.push(charLen);
    if (state.recent_user_lengths.length > 3) state.recent_user_lengths.shift();

    // 疲态判定：若连续 2 轮字数 <= 10（或总字符 < 20），置位疲态破局
    if (state.recent_user_lengths.length >= 2) {
      const allShort = state.recent_user_lengths.slice(-2).every(len => len <= 10);
      state.pacing_fatigue = allShort;
    } else {
      state.pacing_fatigue = false;
    }

    if (state.pacing_fatigue) {
      console.log(`[TSE Engine] ⚡ 检测到心流疲态 (字数: ${charLen}, 反应停顿: ${Math.round(validDelta / 1000)}s)，激活破局加速！`);
      if (state.cool_off_turns > 0) {
        state.cool_off_turns = 0; // 立即清零冷却 CD，打破沉寂！
      }
    }

    // 寻找用户消息前最近的一条 assistant 消息 (通常为 currentFloor - 1)
    const prevAssistantFloor = currentFloor - 1;

    if (prevAssistantFloor >= 0 && prevAssistantFloor > state.committed_floor) {
      let metaToCommit = state.draft_meta;
      // 容错：若 draft_meta 为空（例如刷新页面后直接接话），从前一楼消息原文中二次提取
      if (!metaToCommit) {
        try {
          const getMessages = this.getApi('getChatMessages');
          if (getMessages) {
            const prevMsgs = getMessages(prevAssistantFloor, { role: 'all', hide_state: 'all' }) || getMessages('-2');
            if (prevMsgs && prevMsgs.length > 0) {
              const prevText = prevMsgs[0].message || prevMsgs[0].mes || prevMsgs[0].text || '';
              metaToCommit = this.extractMeta(prevText);
            }
          }
        } catch (e) {}
      }

      console.log(`[TSE Engine] 🔒 玩家接话，正式定稿第 ${prevAssistantFloor + 1} 楼 AI 表现，触发结算！`);
      this.commitTurn(state, metaToCommit, prevAssistantFloor);
      state.committed_floor = prevAssistantFloor;
      state.draft_meta = null;
    }

    // 为即将到来的 AI 回复打出新卡牌（若当前无活跃 buff 且不在蓄水期）
    if (!state.active_buff) {
      if (state.cool_off_turns > 0) {
        state.cool_off_turns -= 1;
        console.log(`[TSE Engine] 当前处于发糖沉淀与蓄水期，剩余空档回合: ${state.cool_off_turns}`);
      } else {
        this.drawAndPlayCard(state, currentFloor);
      }
    }

    this.saveState(state);

    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
  }

  /**
   * 两阶段提交：正式定稿结算某一楼层
   */
  commitTurn(state, meta, floorId) {
    // 1. 步进当前 D0 提示词的 TTL (含 sweet 达成自判定提前核销 Early-Exit)
    this.stepTtl(state, meta);

    // 2. 贝叶斯平滑微漂移与 DMP 偏好沉淀 (引入全域双向动力学离心阻尼：正向减半防温水，负向小摩擦不误伤、大冲突超线性离心放大)
    if (meta) {
      const obsX = typeof meta.x === 'number' ? dampObsDynamic(Math.max(-1, Math.min(1, meta.x))) : state.coord[0];
      const obsY = typeof meta.y === 'number' ? dampObsDynamic(Math.max(-1, Math.min(1, meta.y))) : state.coord[1];
      const newX = state.coord[0] * (1 - SMOOTH_ALPHA) + obsX * SMOOTH_ALPHA;
      const newY = state.coord[1] * (1 - SMOOTH_ALPHA) + obsY * SMOOTH_ALPHA;
      state.coord = [Number(newX.toFixed(3)), Number(newY.toFixed(3))];

      if (meta.target && meta.target !== 'none') {
        state.last_target = meta.target;
        const tMatch = meta.target.match(/^([^\[]+)(?:\[(.*?)\])?$/);
        if (tMatch) {
          const name = tMatch[1].trim();

          // 核心铁律：若本轮为 10% 远方羁绊回响派遣，不计入总榜好感度统计（防滚雪球膨胀）
          const isRemoteEcho = !!(state.dmp?.is_remote_echo && (state.dmp?.current_focus === name));
          if (!isRemoteEcho) {
            state.dmp.affinity_targets[name] = (state.dmp.affinity_targets[name] || 0) + 1;
          } else {
            console.log(`[TSE Engine] 🕊️ 角色【${name}】本次为 10% 远方羁绊回响客串，触发防膨胀保护，不计入总榜好感度！`);
          }

          // 滑动窗口：无论是否远方回响，均压入最近 10 回合活跃队列
          if (!Array.isArray(state.dmp.recent_targets)) {
            state.dmp.recent_targets = [];
          }
          state.dmp.recent_targets.push(name);
          if (state.dmp.recent_targets.length > 10) {
            state.dmp.recent_targets.shift();
          }
        }
      }
      // 结算完毕后重置本轮回响状态
      if (state.dmp) {
        state.dmp.is_remote_echo = false;
      }
      if (meta.note) {
        state.last_note = meta.note;
      }
      if (meta.hit) {
        state.total_hits = (state.total_hits || 0) + 1;
      }

      // 3. 跨象限相位突变检测
      const newQuadrant = detectQuadrant(newX, newY, state.confirmed_quadrant);
      if (newQuadrant !== state.confirmed_quadrant) {
        console.log(`[TSE Engine] ⚠️ 跨象限突变触发: ${state.confirmed_quadrant} -> ${newQuadrant}，立即重组洗牌！`);
        state.confirmed_quadrant = newQuadrant;
        state.hand = buildHand(state.coord, newQuadrant, state.custom_operators, state.active_flavors, state.custom_deck, state.pacing_fatigue, state.graveyard || []);
        state.recently_played = [];
      }
    }
  }

  /**
   * 处理 Swipe 划动事件
   */
  async onSwipeStep(messageId) {
    if (this.isProcessing) return;
    this.isProcessing = true;
    try {
      const getMessages = this.getApi('getChatMessages');
      const getVars = this.getApi('getVariables');
      if (!getMessages || !getVars) return;

      const currentVars = getVars({ type: 'chat' }) || {};
      let state = currentVars.tse_engine || this.memoryState || this.createDefaultState();
      this.memoryState = state;


      // 读取切换后的该楼层消息
      const msgs = getMessages(messageId, { role: 'all', hide_state: 'all' });
      if (msgs && msgs.length > 0) {
        const swipedMsg = msgs[0];
        const text = swipedMsg.message || swipedMsg.mes || swipedMsg.text || '';
        const meta = this.extractMeta(text);
        state.draft_meta = meta || null;
        console.log(`[TSE Engine] 🔄 Swipe 刷新草稿元数据:`, meta);
      }

      // 记录最新 AI 切换完成时间
      this.lastAiCompletedAt = Date.now();

      this.saveState(state);

      if (this.hud && this.hud.isOpen) {
        this.hud.render();
      }
    } catch (err) {
      console.warn('[TSE Engine] onSwipeStep 异常:', err);
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * 抽取并打出一张卡牌 (记录人类可读楼层周期)
   */
  drawAndPlayCard(state, currentFloor = 0) {
    const activeFlavors = state.active_flavors || ['sweet', 'spicy'];
    const customDeck = state.custom_deck || [];
    const ops = getEffectiveOperators(state.custom_operators || {}, activeFlavors, customDeck);
    let playable = state.hand.filter(c => c.durability > 0);

    if (playable.length === 0) {
      // 当前在手 9 张牌已全部耗尽！
      // 检查总牌库中未出场的可用卡牌余量
      const unplayedOps = ops.filter(op => !(state.graveyard || []).includes(op.id));

      if (unplayedOps.length < 9) {
        // 总牌库（27~36张）已完全（或接近完全）轮转耗尽，触发全新大周期洗牌
        console.log(`[TSE Engine] 🔄 全牌库大轮回达成！已完成全量轮转 (已消耗 ${(state.graveyard || []).length} 张，剩余未出场 ${unplayedOps.length} 张)，清空墓地，开启全新大轮回！`);
        state.graveyard = [];
      } else {
        console.log(`[TSE Engine] 🎴 当前手牌用尽，从剩余备用库中选拔全新 9 张手牌 (尚余 ${unplayedOps.length} 张未出场)，外围高张力算子顺位登场！`);
      }

      state.hand = buildHand(state.coord, state.confirmed_quadrant, state.custom_operators, activeFlavors, customDeck, state.pacing_fatigue, state.graveyard || []);
      state.recently_played = [];
      playable = state.hand;
    }

    let candidates = playable.filter(c => !state.recently_played.includes(c.id));
    if (candidates.length === 0) {
      candidates = playable;
    }

    candidates.sort((a, b) => {
      const opA = ops.find(o => o.id === a.id) || a;
      const opB = ops.find(o => o.id === b.id) || b;
      let distA = Math.hypot(opA.anchor[0] - state.coord[0], opA.anchor[1] - state.coord[1]);
      let distB = Math.hypot(opB.anchor[0] - state.coord[0], opB.anchor[1] - state.coord[1]);

      // 若处于疲态，劲辣算子优先推荐吸附
      if (state.pacing_fatigue) {
        if (opA.flavor === 'spicy') distA = Math.max(0, distA - 0.4);
        if (opB.flavor === 'spicy') distB = Math.max(0, distB - 0.4);
      }

      // 多风味激活时探索加成：若上一轮已出某风味，对其它风味给予适度距离加成，避免单一风味连续垄断
      if (state.last_played_flavor && activeFlavors.length > 1 && !state.pacing_fatigue) {
        if ((opA.flavor || 'sweet') !== state.last_played_flavor && (opB.flavor || 'sweet') === state.last_played_flavor) {
          distA = Math.max(0, distA - 0.15);
        } else if ((opB.flavor || 'sweet') !== state.last_played_flavor && (opA.flavor || 'sweet') === state.last_played_flavor) {
          distB = Math.max(0, distB - 0.15);
        }
      }

      return distA - distB;
    });

    // Top-3 距离加权轮盘赌抽样 (Rank 1: 50%, Rank 2: 30%, Rank 3: 20%)，兼顾心流粘合度与博弈探索新鲜感
    let selectedCard = candidates[0];
    if (candidates.length >= 3) {
      const roll = Math.random();
      if (roll < 0.50) {
        selectedCard = candidates[0]; // 50% 概率出最契合卡牌
      } else if (roll < 0.80) {
        selectedCard = candidates[1]; // 30% 概率出次优卡牌
      } else {
        selectedCard = candidates[2]; // 20% 概率出第3优卡牌
      }
    } else if (candidates.length === 2) {
      selectedCard = Math.random() < 0.65 ? candidates[0] : candidates[1];
    }

    selectedCard.durability -= 1;

    if (selectedCard.durability <= 0) {
      if (!state.graveyard.includes(selectedCard.id)) {
        state.graveyard.push(selectedCard.id);
      }
    }

    state.recently_played.push(selectedCard.id);
    if (state.recently_played.length > COOLDOWN_MAX) {
      state.recently_played.shift();
    }

    state.last_played_flavor = selectedCard.flavor || 'sweet';

    const duration = (typeof state.settings?.sweet_duration === 'number' && state.settings.sweet_duration >= 1)
      ? Math.floor(state.settings.sweet_duration)
      : DEFAULT_TTL;

    // 决策当前发糖聚焦目标与 10% 远方羁绊回响
    const resolvedDmp = resolveDmpTarget(state.dmp, currentFloor);
    if (state.dmp) {
      state.dmp.current_focus = resolvedDmp.target;
      state.dmp.is_remote_echo = resolvedDmp.isRemoteEcho;
    }

    // 记录人类可读楼层生命周期与人格象限
    state.active_buff = {
      id: selectedCard.id,
      name: selectedCard.name,
      flavor: selectedCard.flavor || 'sweet',
      intent: selectedCard.intent,
      type: selectedCard.type,
      durability_left: selectedCard.durability,
      target: resolvedDmp.target || null,
      note: state.last_note,
      coord: state.coord,
      quadrant: state.confirmed_quadrant,
      start_floor: currentFloor,
      end_floor: currentFloor + duration,
      remaining_ttl: duration
    };

    injectD0Prompt(this.getApi.bind(this), state.active_buff, state.dmp, state.settings, state);
    console.log(`[TSE Engine] 成功打出卡牌: 【${selectedCard.name}】(${selectedCard.flavor === 'spicy' ? '劲辣' : '蜜糖'})(${selectedCard.type})，楼层区间: 第 ${currentFloor + 1} 楼 ~ 第 ${currentFloor + duration + 1} 楼`);
  }

  /**
   * 动态设置激活的风味包 (支持 'sweet', 'spicy', 'custom')
   * 支持中途随时勾选/取消勾选，平滑自愈：若在场卡牌风味被取消，立即提前核销并从新风味池无缝换发
   */
  async setActiveFlavors(flavors) {
    const state = this.getState();
    const newFlavors = Array.isArray(flavors) && flavors.length > 0 ? flavors : ['sweet', 'spicy'];
    state.active_flavors = newFlavors;

    // 1. 若当前在场卡牌所属风味已被取消勾选，立即提前核销并撤销 D0
    let cardRevoked = false;
    if (state.active_buff) {
      const buffFlavor = state.active_buff.flavor || 'sweet';
      if (!newFlavors.includes(buffFlavor)) {
        console.log(`[TSE Engine] 玩家已取消【${buffFlavor}】风味，在场卡牌【${state.active_buff.name}】立即提前核销！`);
        const uninject = this.getApi('uninjectPrompts');
        if (uninject) {
          uninject([INJECT_ID]);
        }
        state.active_buff = null;
        cardRevoked = true;
      }
    }

    // 2. 净化墓地：移除非激活风味的幽灵卡牌 ID
    const validOps = getEffectiveOperators(state.custom_operators || {}, newFlavors, state.custom_deck);
    const validOpIds = new Set(validOps.map(op => op.id));
    state.graveyard = (state.graveyard || []).filter(id => validOpIds.has(id));

    // 3. 检查未出场卡牌余量：若因缩容导致未出场牌不足 9 张，自动原地开启新规模大轮回
    const unplayedCount = validOps.filter(op => !state.graveyard.includes(op.id)).length;
    if (unplayedCount < 9) {
      console.log(`[TSE Engine] 风味变更后未出场牌库不足 9 张 (${unplayedCount}/${validOps.length})，自动重置大轮回！`);
      state.graveyard = [];
    }

    // 4. 重新按新风味池洗牌与均衡配额构建手牌 (支持墓地不放回排除)
    state.hand = buildHand(state.coord, state.confirmed_quadrant, state.custom_operators, state.active_flavors, state.custom_deck, state.pacing_fatigue, state.graveyard || []);
    state.recently_played = [];

    // 5. 若刚才核销了被取消风味的卡牌，立即从新风味池中无缝抽取新卡补位挂载
    if (cardRevoked) {
      const currentFloor = this.getApi('getLastMessageId') ? (this.getApi('getLastMessageId')() || 0) : 0;
      console.log(`[TSE Engine] 从新风味池【${newFlavors.join('/')}】无缝换发新卡补位...`);
      this.drawAndPlayCard(state, currentFloor);
    }

    this.saveState(state);
    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
  }

  /**
   * 存储自定义生成的 12 算子甲板 (含在场失效平滑换发自愈)
   */
  async setCustomDeck(deck) {
    const state = this.getState();
    state.custom_deck = Array.isArray(deck) ? deck : [];

    let cardRevoked = false;
    if (state.active_buff && state.active_buff.flavor === 'custom') {
      const stillExists = state.custom_deck.some(d => d.id === state.active_buff.id);
      if (!stillExists) {
        console.log(`[TSE Engine] 定制卡包已重置，在场定制卡牌【${state.active_buff.name}】提前退出！`);
        const uninject = this.getApi('uninjectPrompts');
        if (uninject) {
          uninject([INJECT_ID]);
        }
        state.active_buff = null;
        cardRevoked = true;
      }
    }

    // 净化墓地：旧定制卡牌 ID 从墓地清除，新定制卡牌作为 100% 崭新血液
    const newCustomIds = new Set(state.custom_deck.map(d => d.id));
    state.graveyard = (state.graveyard || []).filter(id => {
      if (id.startsWith('X') || id.startsWith('custom_')) {
        return newCustomIds.has(id);
      }
      return true;
    });

    const validOps = getEffectiveOperators(state.custom_operators || {}, state.active_flavors, state.custom_deck);
    const unplayedCount = validOps.filter(op => !state.graveyard.includes(op.id)).length;
    if (unplayedCount < 9) {
      state.graveyard = [];
    }

    state.hand = buildHand(state.coord, state.confirmed_quadrant, state.custom_operators, state.active_flavors, state.custom_deck, state.pacing_fatigue, state.graveyard || []);
    state.recently_played = [];

    if (cardRevoked) {
      const currentFloor = this.getApi('getLastMessageId') ? (this.getApi('getLastMessageId')() || 0) : 0;
      console.log(`[TSE Engine] 定制卡包变更后无缝换发新卡补位...`);
      this.drawAndPlayCard(state, currentFloor);
    }

    this.saveState(state);
    if (this.hud && this.hud.isOpen) {
      this.hud.render();
    }
  }

  /**
   * TTL 步进与超时自动撤销 (含 sweet 达成自判定提前核销 Early-Exit)
   */
  stepTtl(state, meta = null) {
    if (!state.active_buff) return;

    const cooldown = (typeof state.settings?.sweet_cooldown === 'number' && state.settings.sweet_cooldown >= 0)
      ? Math.floor(state.settings.sweet_cooldown)
      : DEFAULT_COOLDOWN;

    // 1. 检查大模型是否在 meta.sweet 中自主回报已完成发糖 (Early-Exit)
    const isSweetDelivered = Boolean(
      meta &&
      meta.sweet &&
      !['none', 'false', 'null', '0', 'undefined', ''].includes(String(meta.sweet).toLowerCase().trim())
    );

    if (isSweetDelivered) {
      console.log(`[TSE Engine] 🎯 AI 伴生元数据自检报告发糖达成 (sweet="${meta.sweet}")，卡牌【${state.active_buff.name}】功成身退，提前核销！`);
      const uninject = this.getApi('uninjectPrompts');
      if (uninject) {
        uninject([INJECT_ID]);
      }
      state.active_buff = null;
      state.cool_off_turns = cooldown;
      return;
    }

    // 2. 常规 TTL 递减与保底超时自动撤销
    state.active_buff.remaining_ttl -= 1;
    if (state.active_buff.remaining_ttl <= 0) {
      console.log(`[TSE Engine] 卡牌【${state.active_buff.name}】TTL 耗尽，自动注销 D0 提示词`);
      const uninject = this.getApi('uninjectPrompts');
      if (uninject) {
        uninject([INJECT_ID]);
      }
      state.active_buff = null;
      state.cool_off_turns = cooldown;
    }
  }

  /**
   * 卸载与清理
   */
  destroy() {
    this.disposers.forEach(stop => {
      try { stop(); } catch (e) {}
    });
    this.disposers = [];

    uninjectAllPrompts(this.getApi.bind(this));

    if (this.hud) {
      this.hud.unmount();
    }
    this.lastMessageSignature = null;
    this.isProcessing = false;
    this.memoryState = null;
  }
}

